    popup.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleInvite();
        }
    });

    invitePopupInitialized = true;
    log('Sidebar', 'Invite popup initialized');
}

