        } else { planHtml += '<p>No items locked in.</p>'; }
        planHtml += '<h3>Favorited Ideas</h3>';
        if (favoritedItems.size > 0) {
            favoritedItems.forEach((info, id) => {
                const item = catalogMap.get(id);
