}

.itinerary-item:hover {
    box-shadow: 0 4px 16px rgba(0,0,0,0.1);
    transform: translateY(-2px);
}

.itinerary-item-clickable {
    cursor: pointer;
}

.itinerary-item-number {
    width: 36px;
    height: 36px;
    background: #007bff;
    color: #fff;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 1em;
    flex-shrink: 0;
}

.itinerary-item-content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.itinerary-media-carousel {
    width: 100%;
}

.itinerary-main-image {
    width: 100%;
    height: 250px;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    border-radius: 8px;
    background-color: #f8f9fa;
}

.itinerary-thumbnails {
    display: flex;
    gap: 8px;
    margin-top: 10px;
    overflow-x: auto;
    padding-bottom: 5px;
}

.itinerary-thumbnail {
    width: 60px;
    height: 45px;
    background-size: cover;
    background-position: center;
    border-radius: 4px;
    cursor: pointer;
    border: 2px solid transparent;
    flex-shrink: 0;
    transition: border-color 0.2s, opacity 0.2s;
    opacity: 0.7;
}

.itinerary-thumbnail:hover {
    opacity: 1;
}

.itinerary-thumbnail.active {
    border-color: #007bff;
    opacity: 1;
}

.itinerary-item-no-images {
    width: 100%;
    height: 150px;
    background: #f8f9fa;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-style: italic;
}

.itinerary-item-details {
    flex: 1;
}

.itinerary-item-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 8px;
}

.itinerary-item-name {
    font-size: 1.2em;
    font-weight: 600;
    color: #212529;
    margin: 0;
    flex: 1;
}

.itinerary-item-type {
    font-size: 0.75em;
    padding: 4px 10px;
    border-radius: 12px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    flex-shrink: 0;
}

.item-type-idea {
    background: #fff3cd;
    color: #856404;
}

.item-type-confirmed {
    background: #d4edda;
    color: #155724;
}

.itinerary-item-price-qty {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
}

.itinerary-item-price {
    font-size: 1.15em;
    font-weight: 600;
    color: #007bff;
}

.itinerary-item-qty {
    font-size: 0.9em;
    color: #6c757d;
}

.itinerary-item-description {
    font-size: 0.95em;
    color: #495057;
    line-height: 1.5;
    margin: 0 0 10px 0;
}

.itinerary-item-note {
    background: #f8f9fa;
    padding: 12px 15px;
    border-radius: 6px;
    font-size: 0.9em;
    color: #495057;
    margin-bottom: 15px;
    border-left: 3px solid #007bff;
}

.itinerary-item-note strong {
    color: #212529;
}

.itinerary-item-reactions {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid #eee;
}

.itinerary-item-reactions .reaction-bar-buttons {
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
    margin-bottom: 8px;
}

.itinerary-item-reactions .reaction-btn {
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 20px;
    font-size: 18px;
    padding: 4px 10px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.itinerary-item-reactions .reaction-btn:hover {
    transform: scale(1.1);
    border-color: #999;
}

.itinerary-item-reactions .reaction-btn.selected {
    background-color: #e7f3ff;
