}

/* Expand/More Details Button for itinerary items */
.itinerary-item-expand-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    padding: 8px 14px;
    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
    border: 1px solid #dee2e6;
    border-radius: 8px;
    font-size: 0.85em;
    font-weight: 500;
    color: #495057;
    cursor: pointer;
    transition: all 0.2s ease;
}

.itinerary-item-expand-btn:hover {
    background: linear-gradient(135deg, #e9ecef 0%, #dee2e6 100%);
    border-color: #ced4da;
    color: #212529;
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.itinerary-item-expand-btn:active {
    transform: translateY(0);
    box-shadow: none;
}

.itinerary-item-expand-btn .expand-btn-icon {
    font-size: 1em;
    transition: transform 0.2s ease;
}

.itinerary-item-expand-btn:hover .expand-btn-icon {
    transform: translate(1px, -1px);
}

.itinerary-item-expand-btn .expand-btn-text {
    white-space: nowrap;
}

.itinerary-chat {
    background: transparent;
    border-top: none;
}

.itinerary-chat-messages {
    max-height: 400px;
    overflow-y: auto;
    padding: 15px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.3);
}

.itinerary-chat-messages .message-wrapper {
    margin-bottom: 12px;
}

.chat-empty,
.itinerary-loading,
.itinerary-empty,
.no-collaborators {
    text-align: center;
    color: #6c757d;
    padding: 30px 20px;
    font-style: italic;
}

/* Presentation View Empty State with Recommendations */
.presentation-empty-state {
    text-align: center;
    padding: 60px 30px;
    max-width: 500px;
    margin: 0 auto;
}

.itinerary-empty-title {
    font-size: 1.4em;
    font-weight: 600;
    color: #333;
    margin: 0 0 10px 0;
    font-style: normal;
}

.itinerary-empty-subtitle {
    font-size: 1em;
    color: #6c757d;
    margin: 0 0 25px 0;
    font-style: normal;
}

.presentation-suggestions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
}

.presentation-suggestion-btn {
    padding: 12px 18px;
    font-size: 0.95em;
    border-radius: 8px;
    background: linear-gradient(135deg, #007bff 0%, #0056b3 100%);
    color: #fff;
    border: none;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s, background 0.2s;
    font-weight: 500;
}

.presentation-suggestion-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(0, 123, 255, 0.4);
    background: linear-gradient(135deg, #0056b3 0%, #003d82 100%);
}

.presentation-suggestion-btn:active {
    transform: translateY(0);
}

/* Mobile responsive for itinerary */
@media (max-width: 768px) {
    .presentation-header .header-content {
        padding: 0.75rem 1rem;
        gap: 10px;
    }

    .presentation-shop-title {
        display: none;
    }

    .presentation-event-label {
        font-size: 0.9em;
        max-width: 150px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .event-emoji-indicator {
        margin-left: 5px;
        padding: 2px 6px;
        font-size: 0.85em;
    }

    .event-emoji-indicator .event-emoji-count {
        font-size: 0.65em;
        padding: 1px 4px;
        min-width: 14px;
    }

    .presentation-header-total {
        font-size: 0.9em;
        padding: 3px 8px;
    }

    .presentation-itinerary-scroll {
        padding: 15px;
    }

    .itinerary-section {
        padding: 20px 15px;
        margin-bottom: 15px;
    }

    .itinerary-event-title {
        font-size: 1.5em;
    }

    .itinerary-item {
        flex-direction: column;
        gap: 15px;
        padding: 15px;
    }

    .itinerary-item-number {
        width: 30px;
        height: 30px;
        font-size: 0.9em;
    }

    .itinerary-main-image {
        height: 200px;
    }

    .itinerary-item-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 8px;
    }

    .itinerary-item-name {
        font-size: 1.1em;
    }

    .collaborators-list {
        flex-direction: column;
        align-items: center;
    }

    /* Collaborators Carousel mobile styles */
    .collaborators-carousel-wrapper {
        gap: 4px;
    }

    .collaborators-carousel {
        max-width: calc(100% - 70px);
        gap: 8px;
    }

    .collaborators-carousel-btn {
        width: 28px;
        height: 28px;
        font-size: 1em;
    }

    .collaborators-expand-btn {
        font-size: 0.8em;
        padding: 5px 14px;
    }

    .collaborators-modal-content {
        width: 95%;
        max-height: 80vh;
    }

    .itinerary-chat-messages {
        max-height: 300px;
    }
}

/* Accordion Styles for Presentation View */
.itinerary-accordion {
    overflow: hidden;
}

.itinerary-accordion-header {
    cursor: pointer;
    padding: 15px 0;
    user-select: none;
    transition: padding 0.3s ease;
}

.itinerary-accordion-header:hover {
    background: rgba(0, 123, 255, 0.03);
}

.itinerary-accordion-title-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
}

.itinerary-accordion-title {
    font-size: 1.3em;
    font-weight: 600;
    color: #333;
    margin: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.itinerary-accordion-icon {
    display: inline-block;
    width: 24px;
    height: 24px;
    position: relative;
    flex-shrink: 0;
    transition: transform 0.3s ease;
}

.itinerary-accordion-icon::before,
.itinerary-accordion-icon::after {
    content: '';
    position: absolute;
    background-color: #007bff;
    transition: transform 0.3s ease, opacity 0.3s ease;
}

.itinerary-accordion-icon::before {
    width: 2px;
    height: 14px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.itinerary-accordion-icon::after {
    width: 14px;
    height: 2px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

/* Expanded state - hide the vertical line to show minus */
.itinerary-accordion.expanded .itinerary-accordion-icon::before {
    transform: translate(-50%, -50%) rotate(90deg);
    opacity: 0;
}

.itinerary-accordion-summary {
    font-size: 0.9em;
    color: #6c757d;
    margin: 10px 0 0 0;
    line-height: 1.4;
    max-height: 60px;
    overflow: hidden;
    transition: opacity 0.3s ease, max-height 0.3s ease;
}

/* Hide summary when expanded */
.itinerary-accordion.expanded .itinerary-accordion-summary {
    opacity: 0;
    max-height: 0;
    margin-top: 0;
}

/* Accordion section title (e.g., plan name in header) */
.accordion-section-title {
    font-size: 1.2em;
    font-weight: 600;
    color: #333;
    margin: 0;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    opacity: 1;
    transition: opacity 0.3s ease;
}

/* Accordion section title stays visible in both collapsed and expanded states */
.itinerary-accordion:not(.expanded) .accordion-section-title {
    opacity: 1;
}

.itinerary-accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.3s ease;
    padding-top: 0;
}

/* Expanded state */
.itinerary-accordion.expanded .itinerary-accordion-content {
    max-height: 3000px;
    padding-top: 15px;
    overflow: visible;
}

/* Remove old title styling when inside accordion */
.itinerary-accordion .itinerary-section-title {
    display: none;
}

/* Adjust header section styling for accordion */
.itinerary-accordion.itinerary-header {
    text-align: left;
}

.itinerary-accordion.itinerary-header.expanded {
    text-align: center;
}

.itinerary-accordion.itinerary-header .itinerary-accordion-content {
    text-align: center;
}

/* Section-specific accordion styles */
.itinerary-accordion.itinerary-header .itinerary-accordion-header {
    text-align: left;
}

.itinerary-accordion.itinerary-items .itinerary-accordion-header,
