   ============================================ */

/* Reset the base itinerary-item styles for accordion mode */
.itinerary-item.item-accordion {
    display: block;
    padding: 0;
    overflow: hidden;
    cursor: default;
}

/* Item Accordion Header - Always visible */
.item-accordion-header {
    cursor: pointer;
    padding: 15px 20px;
    user-select: none;
    transition: background-color 0.2s ease, padding 0.3s ease;
    background: linear-gradient(135deg, rgba(255,255,255,0.95) 0%, rgba(248,249,250,0.9) 100%);
}

.item-accordion-header:hover {
