    background: none;
    cursor: pointer;
    font-size: 0.95em;
    color: #333;
    text-align: left;
    transition: background-color 0.15s;
}

.share-dropdown-item:hover {
    background-color: #f8f9fa;
}

.share-dropdown-item:active {
    background-color: #e9ecef;
}

.share-item-icon {
    margin-right: 10px;
    font-size: 1.1em;
}

.share-dropdown-divider {
    border: none;
    border-top: 1px solid #dee2e6;
    margin: 0;
}

/* Hamburger Menu Styles */
#hamburger-menu-container {
    position: relative;
}

#hamburger-menu-btn {
    font-size: 1.4em;
}

.hamburger-icon {
    line-height: 1;
}

.hamburger-dropdown {
