}

.share-rsvp-row {
    display: flex;
    justify-content: space-between;
    gap: 10px;
}

.share-rsvp-item {
    text-align: center;
    flex: 1;
}

.share-rsvp-count {
    font-size: 1.2em;
    font-weight: bold;
    display: block;
}

.share-rsvp-count.going {
