.quick-pay-tip-custom-input {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 12px;
    padding: 10px 12px;
    background: #fff;
    border: 2px solid #6D1ED4;
    border-radius: 8px;
}

.quick-pay-tip-currency {
    font-weight: 600;
    color: #6D1ED4;
    font-size: 1.1em;
}

.quick-pay-tip-input {
    flex: 1;
    border: none;
    outline: none;
    font-size: 1em;
    font-weight: 500;
