/*
 * Version: 2.0.0
 * Last Modified: 2025-09-19
 *
 * Changelog:
 *
 * v2.0.0 - 2025-09-19
 * - Replaced hardcoded file list with a dynamic file walker.
 * - The script now recursively finds all relevant source files (.js, .html, .css, .md, .json, .toml).
 * - Added an ignore list for directories like node_modules.
 *
 * v1.1.0 - 2025-08-18
 * - Added logic to read and combine all project files into project_source.txt during build.
 */
const fs = require('fs');
const path = require('path');

const projectRoot = __dirname;

// Define which file extensions and specific files to include
const includeExtensions = ['.js', '.html', '.css', '.md', '.json', '.toml'];
const includeFiles = ['LICENSE', 'README']; // Add specific root files without extensions if needed

// Define directories and files to explicitly ignore
const ignoreList = [
    'node_modules',
    '.git',
    '.DS_Store',
    'package-lock.json',
    'project_source.txt' // Don't include the output file in itself
];

// Recursive function to get all file paths
const getAllFiles = (dirPath, arrayOfFiles = []) => {
    const files = fs.readdirSync(dirPath);

    files.forEach(file => {
        const fullPath = path.join(dirPath, file);
        if (ignoreList.includes(file)) {
            return;
        }
        if (fs.statSync(fullPath).isDirectory()) {
            arrayOfFiles = getAllFiles(fullPath, arrayOfFiles);
        } else {
            const isIncludedExtension = includeExtensions.includes(path.extname(file));
            const isIncludedFile = includeFiles.includes(file);
            if (isIncludedExtension || isIncludedFile) {
                arrayOfFiles.push(fullPath);
            }
        }
    });

    return arrayOfFiles;
};

// Get all project files and format them for the output
try {
    const allProjectFiles = getAllFiles(projectRoot);

    const outputContent = allProjectFiles.map(filePath => {
        // Create a relative path from the project root for cleaner headers
        const relativePath = path.relative(projectRoot, filePath).replace(/\\/g, '/');
        const content = fs.readFileSync(filePath, 'utf8');
        return `============================================================\n// FILE: ${relativePath}\n============================================================\n${content}`;
    }).join('\n\n');

    const header = `Project Export - ${new Date().toISOString()}\n\n`;
    fs.writeFileSync(path.join(projectRoot, 'project_source.txt'), header + outputContent);
    console.log(`Project source successfully exported to project_source.txt, containing ${allProjectFiles.length} files.`);

} catch (error) {
    console.error('Failed to export project source:', error);
}

const fs = require('fs');
const path = require('path');

// --- Configuration ---
const PROJECT_ROOT = process.cwd();
const OUTPUT_FILE = 'project_source.json';

// Paths to ignore during the export process (relative to PROJECT_ROOT)
const EXCLUDE_PATHS = [
    'node_modules',
    '.git',
    OUTPUT_FILE,                // Exclude the output file itself (project_source.json)
    // The export scripts (export_to_json.js and write_files_from_json.js) 
    // are now included in the export for a complete project package.
    'temp',
    'dist'
];

/**
 * Recursively retrieves a list of all files in a directory, filtering against EXCLUDE_PATHS.
 * @param {string} dir - The directory to search from.
 * @param {string[]} filelist - Accumulator for the list of file paths.
 * @returns {string[]} The list of file paths (relative to PROJECT_ROOT).
 */
function getFilesRecursive(dir, filelist = []) {
    const files = fs.readdirSync(dir);

    files.forEach(file => {
        const filePath = path.join(dir, file);
        const relativePath = path.relative(PROJECT_ROOT, filePath);

        // Check if the file or directory should be ignored
        if (EXCLUDE_PATHS.includes(file) || EXCLUDE_PATHS.includes(relativePath)) {
            return;
        }

        const stats = fs.statSync(filePath);

        if (stats.isDirectory()) {
            filelist = getFilesRecursive(filePath, filelist);
        } else if (stats.isFile()) {
            filelist.push(relativePath);
        }
    });

    return filelist;
}

/**
 * Scans the project directory, reads the content of relevant files, 
 * and exports the entire project structure as a single JSON object.
 */
function exportProjectAsJson() {
    console.log("Starting structured JSON project export...");

    const allFilePaths = getFilesRecursive(PROJECT_ROOT);
    const projectFiles = [];

    // 1. Read content for each file
    allFilePaths.forEach(filePath => {
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            projectFiles.push({
                // Normalize path separators for consistency across systems
                path: filePath.replace(/\\/g, '/'), 
                content: content
            });
        } catch (error) {
            console.error(`[ERROR] Could not read file ${filePath}: ${error.message}`);
        }
    });

    // 2. Construct the final JSON object, including metadata
    const exportData = {
        metadata: {
            exportDate: new Date().toISOString(),
            projectRoot: path.basename(PROJECT_ROOT),
            fileCount: projectFiles.length
        },
        files: projectFiles
    };

    // 3. Write the JSON object to the output file
    try {
        // Use 2 spaces for indentation for readability
        const jsonContent = JSON.stringify(exportData, null, 2); 
        fs.writeFileSync(OUTPUT_FILE, jsonContent);
        console.log(`\nSuccessfully exported ${projectFiles.length} files to ${OUTPUT_FILE}`);
        console.log(`Output file is ready for use by 'write_files_from_json.js' and your GitHub workflow.`);
    } catch (error) {
        console.error(`\n❌ Error writing output file ${OUTPUT_FILE}: ${error.message}`);
        process.exit(1);
    }
}

exportProjectAsJson();

