const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

// Define a simplified fee structure for demonstration (adjust these rates)
// Standard Card: 2.9% + $0.30
// ACH Direct Debit: 0.8% (capped at $5.00)
// Wallet (Apple/Google Pay): Typically same as card (2.9% + $0.30)
function calculateProcessingFee(baseAmountInCents, paymentMethodType) {
  // Defensive: validate inputs
  if (typeof baseAmountInCents !== 'number' || isNaN(baseAmountInCents) || baseAmountInCents < 0) {
    console.warn(`[FeeCalc] Invalid baseAmountInCents: ${baseAmountInCents}, using 0`);
    baseAmountInCents = 0;
  }

  console.log(`[FeeCalc] Starting calculation for type: ${paymentMethodType}, amount: ${baseAmountInCents} cents.`);

  const baseAmount = baseAmountInCents / 100;
  let fee = 0;

  switch (paymentMethodType) {
    // ACH Direct Debit: 0.8%, capped at $5.00
    case 'ach_debit':
    case 'us_bank_account':
      fee = baseAmount * 0.008;
      // Apply max cap of $5.00.
      fee = Math.min(fee, 5.00);
      break;

    // Standard card/wallet fee: 2.9% + $0.30
    case 'cashapp':
    case 'card':
    case 'google_pay':
    case 'apple_pay':
    default:
      const fixedFee = 0.30;
      const percentageRate = 0.029; // 2.9%
      fee = baseAmount * percentageRate + fixedFee;
      break;
  }

  const feeInCents = Math.round(fee * 100);
  console.log(`[FeeCalc] Final fee calculated: ${feeInCents} cents (Rate: ${baseAmount > 0 ? (fee*100/baseAmount).toFixed(2) : 0}%)`);
  return feeInCents;
}

exports.handler = async (event) => {
  // Validate environment variables
  if (!process.env.STRIPE_SECRET_KEY) {
    console.error('[create-payment-intent] Stripe secret key is not configured.');
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Payment provider is not configured correctly.' }),
    };
  }

  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, body: JSON.stringify({ error: 'Method Not Allowed' }) };
  }

  let baseAmountInCents, paymentMethodType;
  try {
    // Defensive: validate request body exists
    if (!event.body) {
      return { statusCode: 400, body: JSON.stringify({ error: 'Missing request body.' }) };
    }

    const body = JSON.parse(event.body);
    baseAmountInCents = body.amount; // This is the subtotal + tip (excluding fee)
    // Client must send the selected payment type for accurate fee calculation
    paymentMethodType = body.paymentMethodType || 'card';
  } catch (error) {
    console.error('[create-payment-intent] Error parsing request body:', error);
    return { statusCode: 400, body: JSON.stringify({ error: 'Invalid request body.' }) };
  }

  console.log(`[create-payment-intent] Received request. Base amount: ${baseAmountInCents} cents, Payment Type: ${paymentMethodType}`);

  // Validate amount
  if (typeof baseAmountInCents !== 'number' || isNaN(baseAmountInCents)) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: `Invalid amount specified: ${baseAmountInCents}` }),
    };
  }

  // Stripe minimum is 50 cents
  if (baseAmountInCents < 50) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: `Amount must be at least 50 cents. Received: ${baseAmountInCents}` }),
    };
  }

  // Cap maximum amount to prevent extreme values (e.g., $1,000,000 = 100000000 cents)
  const MAX_AMOUNT_CENTS = 100000000;
  if (baseAmountInCents > MAX_AMOUNT_CENTS) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: `Amount exceeds maximum allowed.` }),
    };
  }

  try {
    // Calculate the fee and the new total amount (including fee)
    const processingFeeInCents = calculateProcessingFee(baseAmountInCents, paymentMethodType);
    const finalAmountInCents = baseAmountInCents + processingFeeInCents;

    const paymentIntent = await stripe.paymentIntents.create({
      amount: finalAmountInCents, // Charge the full amount including the fee
      currency: 'usd',
      // Allow Stripe to determine the best method types based on the user's element display
      automatic_payment_methods: { enabled: true },
    });

    return {
      statusCode: 200,
      body: JSON.stringify({
          clientSecret: paymentIntent.client_secret,
          processingFeeInCents: processingFeeInCents
      }),
    };
  } catch (error) {
    console.error('[create-payment-intent] Stripe API error:', error.message);
    // Provide more helpful error messages based on Stripe error types
    let userMessage = 'Failed to create payment intent.';
    if (error.type === 'StripeCardError') {
      userMessage = 'There was an issue with the payment method.';
    } else if (error.type === 'StripeInvalidRequestError') {
      userMessage = 'Invalid payment request.';
    }
    return {
      statusCode: 500,
      body: JSON.stringify({ error: userMessage }),
    };
  }
};

// In netlify/functions/get-event-by-slug.js
const fetch = require('node-fetch');
const { AIRTABLE_PAT, BASE_ID } = process.env;

exports.handler = async (event) => {
    const { slug } = event.queryStringParameters;
    if (!slug) {
        return { statusCode: 400, body: 'Missing event slug.' };
    }

    try {
        // 1. Find the Event record using the slug
        const eventFormula = `({Event Slug} = '${slug}')`;
        const eventUrl = `https://api.airtable.com/v0/${BASE_ID}/Events?filterByFormula=${encodeURIComponent(eventFormula)}`;
        const eventResponse = await fetch(eventUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
        const eventData = await eventResponse.json();

        if (!eventData.records || eventData.records.length === 0) {
            return { statusCode: 404, body: 'Event not found.' };
        }
        const eventRecord = eventData.records[0];
        const sessionId = eventRecord.fields.Session[0];

        // 2. Fetch the linked Session record
        const sessionUrl = `https://api.airtable.com/v0/${BASE_ID}/Sessions/${sessionId}`;
        const sessionResponse = await fetch(sessionUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
        if (!sessionResponse.ok) {
            throw new Error('Could not fetch the linked session data.');
        }
        const sessionRecord = await sessionResponse.json();

        // 3. Return all the data together
        return {
            statusCode: 200,
            body: JSON.stringify({
                event: eventRecord,
                session: sessionRecord
            }),
        };
    } catch (error) {
        return { statusCode: 500, body: error.toString() };
    }
};

// netlify/functions/fetch-website-image.js
// Scrapes websites for Open Graph images, meta images, and favicons
// Returns the best available image URL for a given website

const fetch = require('node-fetch');

/**
 * Extracts the best image from HTML content
 * Priority: og:image > twitter:image > link[rel="image_src"] > first large image > favicon
 */
function extractImageFromHTML(html, baseUrl) {
    const results = {
        ogImage: null,
        twitterImage: null,
        linkImage: null,
        favicon: null,
        metaDescription: null
    };

    // Extract og:image
    const ogImageMatch = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i)
        || html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["']/i);
    if (ogImageMatch) {
        results.ogImage = resolveUrl(ogImageMatch[1], baseUrl);
    }

    // Extract twitter:image
    const twitterImageMatch = html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["']/i)
        || html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']twitter:image["']/i);
    if (twitterImageMatch) {
        results.twitterImage = resolveUrl(twitterImageMatch[1], baseUrl);
    }

    // Extract link rel="image_src"
    const linkImageMatch = html.match(/<link[^>]*rel=["']image_src["'][^>]*href=["']([^"']+)["']/i);
    if (linkImageMatch) {
        results.linkImage = resolveUrl(linkImageMatch[1], baseUrl);
    }

    // Extract favicon for last resort
    const faviconMatch = html.match(/<link[^>]*rel=["'](?:shortcut )?icon["'][^>]*href=["']([^"']+)["']/i)
        || html.match(/<link[^>]*href=["']([^"']+)["'][^>]*rel=["'](?:shortcut )?icon["']/i);
    if (faviconMatch) {
        results.favicon = resolveUrl(faviconMatch[1], baseUrl);
    }

    // Extract og:description for context
    const descMatch = html.match(/<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']+)["']/i);
    if (descMatch) {
        results.metaDescription = descMatch[1];
    }

    return results;
}

/**
 * Resolves a potentially relative URL to an absolute URL
 */
function resolveUrl(url, baseUrl) {
    if (!url) return null;

    // Already absolute
    if (url.startsWith('http://') || url.startsWith('https://')) {
        return url;
    }

    // Protocol-relative
    if (url.startsWith('//')) {
        return 'https:' + url;
    }

    try {
        const base = new URL(baseUrl);
        // Root-relative
        if (url.startsWith('/')) {
            return base.origin + url;
        }
        // Relative path
        return new URL(url, baseUrl).href;
    } catch (e) {
        console.error('[fetch-website-image] URL resolution error:', e.message);
        return null;
    }
}

/**
 * Validates if an image URL is likely valid and usable
 */
async function validateImageUrl(imageUrl, timeout = 5000) {
    if (!imageUrl) return false;

    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), timeout);

        const response = await fetch(imageUrl, {
            method: 'HEAD',
            signal: controller.signal,
            headers: {
                'User-Agent': 'Mozilla/5.0 (compatible; WhatTheFunFinder/1.0)'
            }
        });

        clearTimeout(timeoutId);

        if (!response.ok) return false;

        const contentType = response.headers.get('content-type') || '';
        return contentType.startsWith('image/');
    } catch (e) {
        console.log('[fetch-website-image] Image validation failed:', imageUrl, e.message);
        return false;
    }
}

/**
 * Tries to fetch an image from social media profiles
 */
function getSocialMediaImageUrls(businessName, websiteUrl) {
    const socialUrls = [];
    const encodedName = encodeURIComponent(businessName.toLowerCase().replace(/[^a-z0-9]+/g, ''));

    // Common social media profile patterns
    // These return avatar/profile images which can be useful

    // Try Facebook page (many businesses have these)
    socialUrls.push(`https://graph.facebook.com/${encodedName}/picture?type=large`);

    // Try a Google business image search pattern
    // Note: This is a heuristic and may not always work
    socialUrls.push(`https://logo.clearbit.com/${new URL(websiteUrl).hostname}`);

    return socialUrls;
}

exports.handler = async (event) => {
    if (event.httpMethod !== 'POST') {
        return { statusCode: 405, body: JSON.stringify({ error: 'Method Not Allowed' }) };
    }

    try {
        const { websiteUrl, businessName, imageKeywords } = JSON.parse(event.body);

        if (!websiteUrl && !businessName) {
            return {
                statusCode: 400,
                body: JSON.stringify({ error: 'Either websiteUrl or businessName is required' })
            };
        }

        console.log(`[fetch-website-image] Processing request:`, { websiteUrl, businessName, imageKeywords });

        const result = {
            success: false,
            imageUrl: null,
            source: null,
            attempts: []
        };

        // Attempt 1: Scrape the business website for og:image
        if (websiteUrl) {
            try {
                console.log(`[fetch-website-image] Attempt 1: Fetching website ${websiteUrl}`);
                result.attempts.push({ method: 'website_scrape', url: websiteUrl, status: 'trying' });

                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 8000);

                const response = await fetch(websiteUrl, {
                    signal: controller.signal,
                    headers: {
                        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                        'Accept-Language': 'en-US,en;q=0.5'
                    }
                });

                clearTimeout(timeoutId);

                if (response.ok) {
                    const html = await response.text();
                    const images = extractImageFromHTML(html, websiteUrl);

                    console.log(`[fetch-website-image] Extracted images:`, images);

                    // Try images in priority order
                    const candidates = [
                        { url: images.ogImage, source: 'og:image' },
                        { url: images.twitterImage, source: 'twitter:image' },
                        { url: images.linkImage, source: 'link:image_src' }
                    ];

                    for (const candidate of candidates) {
                        if (candidate.url) {
                            const isValid = await validateImageUrl(candidate.url);
                            if (isValid) {
                                result.success = true;
                                result.imageUrl = candidate.url;
                                result.source = candidate.source;
                                result.attempts[result.attempts.length - 1].status = 'success';
                                result.attempts[result.attempts.length - 1].foundImage = candidate.source;

                                console.log(`[fetch-website-image] SUCCESS via ${candidate.source}:`, candidate.url);

                                return {
                                    statusCode: 200,
                                    body: JSON.stringify(result)
                                };
                            }
                        }
                    }

                    result.attempts[result.attempts.length - 1].status = 'no_valid_images';
                } else {
                    result.attempts[result.attempts.length - 1].status = `http_${response.status}`;
                }
            } catch (fetchError) {
                console.log(`[fetch-website-image] Website fetch failed:`, fetchError.message);
                result.attempts[result.attempts.length - 1].status = 'error';
                result.attempts[result.attempts.length - 1].error = fetchError.message;
            }
        }

        // Attempt 2: Try Clearbit Logo API (free, no auth required for basic usage)
        if (websiteUrl) {
            try {
                const hostname = new URL(websiteUrl).hostname.replace('www.', '');
