        console.error("Pusher library is not loaded. Real-time features will be disabled.");
        return null;
    }

    try {
        // Access Pusher from the global 'window' object, not an import
        const pusher = new window.Pusher(key, {
            cluster: cluster,
            encrypted: true,
            authEndpoint: '/api/pusher-auth',
            auth: {
                params: { sessionId: sessionId }
            }
        });

        pusherInstance = pusher;
        log('Pusher', 'Pusher client initialized.');
        return pusher;

    } catch (error) {
        console.error("Failed to initialize Pusher:", error);
        return null;
    }
}

/**
 * Get the current Pusher instance
 * @returns {Object|null} - Current Pusher instance
 */
export function getPusherInstance() {
    return pusherInstance;
}

/**
 * Subscribe to a project channel for real-time updates
 * @param {string} projectId - The project ID to subscribe to
 * @param {Object} callbacks - Object containing event handler callbacks
 * @returns {Object|null} - The subscribed channel or null
 */
export function subscribeToProject(projectId, callbacks = {}) {
    if (!pusherInstance) {
        log('Pusher', 'Cannot subscribe to project - Pusher not initialized');
        return null;
    }

    if (!projectId) {
        log('Pusher', 'Cannot subscribe to project - no project ID provided');
        return null;
    }

    // Unsubscribe from previous project if different
    if (currentSubscribedProjectId && currentSubscribedProjectId !== projectId) {
        unsubscribeFromProject();
    }

    // Already subscribed to this project
    if (currentSubscribedProjectId === projectId && projectChannel) {
        log('Pusher', `Already subscribed to project: ${projectId}`);
        return projectChannel;
    }

    try {
        const channelName = `private-project-${projectId}`;
        projectChannel = pusherInstance.subscribe(channelName);
        currentSubscribedProjectId = projectId;

        log('Pusher', `Subscribed to project channel: ${channelName}`);

        // Bind to project-related events
        bindProjectEvents(projectChannel, callbacks);

        return projectChannel;
    } catch (error) {
        console.error('Failed to subscribe to project channel:', error);
        return null;
    }
}

/**
 * Unsubscribe from the current project channel
 */
export function unsubscribeFromProject() {
    if (projectChannel && currentSubscribedProjectId) {
        const channelName = `private-project-${currentSubscribedProjectId}`;

        // Unbind all events
        eventListeners.forEach((handler, eventName) => {
            projectChannel.unbind(eventName, handler);
        });
        eventListeners.clear();

        // Unsubscribe from channel
        if (pusherInstance) {
            pusherInstance.unsubscribe(channelName);
        }

        log('Pusher', `Unsubscribed from project channel: ${channelName}`);

        projectChannel = null;
        currentSubscribedProjectId = null;
    }
}

/**
 * Bind event handlers to project channel
 * @param {Object} channel - Pusher channel
 * @param {Object} callbacks - Event handler callbacks
 */
function bindProjectEvents(channel, callbacks) {
    // Task events
    const taskEvents = [
        { event: 'task-created', handler: callbacks.onTaskCreated },
        { event: 'task-updated', handler: callbacks.onTaskUpdated },
        { event: 'task-deleted', handler: callbacks.onTaskDeleted },
        { event: 'task-reordered', handler: callbacks.onTaskReordered }
    ];

    // Project events
    const projectEvents = [
        { event: 'project-status-changed', handler: callbacks.onProjectStatusChanged },
        { event: 'project-updated', handler: callbacks.onProjectUpdated },
        { event: 'item-added', handler: callbacks.onItemAdded },
        { event: 'item-removed', handler: callbacks.onItemRemoved },
        { event: 'collaborator-joined', handler: callbacks.onCollaboratorJoined }
    ];

    const allEvents = [...taskEvents, ...projectEvents];

    allEvents.forEach(({ event, handler }) => {
        if (handler && typeof handler === 'function') {
            channel.bind(event, handler);
            eventListeners.set(event, handler);
            log('Pusher', `Bound handler for event: ${event}`);
        }
    });

    // Always bind a default handler for logging
    channel.bind_global((eventName, data) => {
        log('Pusher', `Received event: ${eventName}`, data);
    });
}

/**
 * Trigger a client event on the project channel
 * Note: Requires private channel and client events enabled
 * @param {string} eventName - Event name (must start with 'client-')
 * @param {Object} data - Event data
 * @returns {boolean} - Whether the event was triggered successfully
 */
export function triggerProjectEvent(eventName, data) {
    if (!projectChannel) {
        log('Pusher', 'Cannot trigger event - not subscribed to project');
        return false;
    }

    // Client events must start with 'client-'
    const fullEventName = eventName.startsWith('client-') ? eventName : `client-${eventName}`;

    try {
        projectChannel.trigger(fullEventName, {
            ...data,
            userId: state.session.user?.id,
            userName: state.session.user?.name,
            timestamp: new Date().toISOString()
        });
        log('Pusher', `Triggered event: ${fullEventName}`);
        return true;
    } catch (error) {
        console.error('Failed to trigger project event:', error);
        return false;
    }
}

/**
 * Get the currently subscribed project ID
 * @returns {string|null} - Current project ID or null
 */
export function getCurrentSubscribedProjectId() {
    return currentSubscribedProjectId;
}

/**
 * Check if currently subscribed to a project
 * @param {string} projectId - Optional project ID to check against
 * @returns {boolean} - Whether subscribed to the project
 */
export function isSubscribedToProject(projectId = null) {
    if (!projectChannel || !currentSubscribedProjectId) {
        return false;
    }
    if (projectId) {
        return currentSubscribedProjectId === projectId;
    }
    return true;
}

// Optimized Service Worker for cache management
// This ensures users always see the latest version of the site

const CACHE_VERSION = 'v-1765920707016'; // Auto-updated during build
const STATIC_CACHE = 'wtfun-static-' + CACHE_VERSION;
const DYNAMIC_CACHE = 'wtfun-dynamic-' + CACHE_VERSION;
const IMAGE_CACHE = 'wtfun-images-' + CACHE_VERSION;
const FONT_CACHE = 'wtfun-fonts-' + CACHE_VERSION;

// Maximum cache sizes to prevent storage bloat
const MAX_IMAGE_CACHE_SIZE = 100;
const MAX_DYNAMIC_CACHE_SIZE = 50;
const IMAGE_CACHE_MAX_AGE = 7 * 24 * 60 * 60 * 1000; // 7 days
const FONT_CACHE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days

// Only cache essential files immediately - lazy load the rest
// Note: critical.css is inlined in index.html, so we don't need to cache it separately
const STATIC_FILES = [
  '/',
  '/index.html',
  '/main.js'
];

// Preload essential resources in the background during idle time
const BACKGROUND_PRELOAD = [
  '/css/deferred.css',
  '/crm.js'
];

// Cache strategy per resource type
const CACHE_STRATEGIES = {
  // HTML - Network first (always try to get fresh content)
  html: 'network-first',
  // JS/CSS - Stale-while-revalidate (serve cached, update in background)
  scripts: 'stale-while-revalidate',
  // Images - Cache first with expiration
  images: 'cache-first',
  // Fonts - Cache first (long-lived)
  fonts: 'cache-first',
  // API calls - Network only (never cache)
  api: 'network-only'
};

// Install event - cache static assets
self.addEventListener('install', (event) => {
  console.log('[SW] Installing service worker...', CACHE_VERSION);

  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) => {
      console.log('[SW] Caching static assets');
      return cache.addAll(STATIC_FILES).catch((err) => {
        console.warn('[SW] Failed to cache some assets:', err);
      });
    }).then(() => {
      return self.skipWaiting(); // Activate immediately
    })
  );
});

// Activate event - clean up old caches
self.addEventListener('activate', (event) => {
  console.log('[SW] Activating new service worker...', CACHE_VERSION);

  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          // Delete all caches that don't match current version
          if (cacheName.startsWith('wtfun-') &&
              cacheName !== STATIC_CACHE &&
              cacheName !== DYNAMIC_CACHE &&
              cacheName !== IMAGE_CACHE &&
              cacheName !== FONT_CACHE) {
            console.log('[SW] Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => {
      // Background preload additional resources
      return caches.open(STATIC_CACHE).then((cache) => {
        console.log('[SW] Background preloading additional resources...');
        return Promise.allSettled(
          BACKGROUND_PRELOAD.map(url =>
            cache.add(url).catch(err => console.log('[SW] Preload skipped:', url))
          )
        );
      });
    }).then(() => {
      return self.clients.claim(); // Take control of all pages immediately
    })
  );
});

// Fetch event - Smart caching strategies based on resource type
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Skip non-GET requests
  if (request.method !== 'GET') {
    return;
  }

  // Skip API calls, Netlify functions, and external domains (except Netlify Image CDN)
  if (url.pathname.includes('/api/') ||
      (url.pathname.includes('/.netlify/') && !url.pathname.includes('/.netlify/images')) ||
      url.pathname.includes('airtable.com') ||
      (url.hostname !== self.location.hostname && !url.pathname.includes('/.netlify/images'))) {
    return;
  }

  // Determine resource type and apply appropriate strategy
  const isImage = /\.(png|jpg|jpeg|gif|webp|svg|avif)$/i.test(url.pathname) ||
                  url.pathname.includes('/.netlify/images') ||
                  url.hostname.includes('cloudinary.com');
  const isFont = /\.(woff2?|ttf|otf|eot)$/i.test(url.pathname);
  const isScript = /\.(js|mjs)$/i.test(url.pathname);
  const isStyle = /\.css$/i.test(url.pathname);
  const isHTML = request.destination === 'document' || url.pathname.endsWith('.html') || url.pathname === '/';

  // Font caching strategy: Cache-first with 30-day expiration (fonts rarely change)
  if (isFont) {
    event.respondWith(
      caches.open(FONT_CACHE).then((cache) => {
        return cache.match(request).then((cached) => {
          if (cached) {
            return cached;
          }

          return fetch(request).then((response) => {
            if (response.ok) {
              cache.put(request, response.clone());
            }
            return response;
          }).catch(() => new Response('Font unavailable', { status: 404 }));
        });
      })
    );
    return;
  }

  // Image caching strategy: Cache-first with 7-day expiration
  // Also cache Netlify Image CDN responses for faster subsequent loads
  if (isImage) {
    event.respondWith(
      caches.open(IMAGE_CACHE).then((cache) => {
        return cache.match(request).then((cached) => {
          if (cached) {
            // Check if cached image is less than 7 days old
            const cachedDate = new Date(cached.headers.get('sw-cached-date'));
            const now = Date.now();
            if (now - cachedDate < 7 * 24 * 60 * 60 * 1000) {
              return cached;
            }
          }

          // Fetch new image and cache it
          return fetch(request).then((response) => {
            if (response.ok) {
              const responseToCache = response.clone();
              const headers = new Headers(responseToCache.headers);
              headers.append('sw-cached-date', new Date().toISOString());

              cache.put(request, new Response(responseToCache.body, {
                status: responseToCache.status,
                statusText: responseToCache.statusText,
                headers: headers
              }));
            }
            return response;
          }).catch(() => cached || new Response('Image unavailable', { status: 404 }));
        });
      })
    );
    return;
  }

  // JS/CSS caching strategy: Stale-while-revalidate
  if (isScript || isStyle) {
    event.respondWith(
      caches.open(STATIC_CACHE).then((cache) => {
        return cache.match(request).then((cached) => {
          const fetchPromise = fetch(request).then((response) => {
            if (response.ok) {
              cache.put(request, response.clone());
            }
            return response;
          }).catch(() => cached);

          // Return cached immediately if available, fetch in background
          return cached || fetchPromise;
        });
      })
    );
    return;
  }

  // HTML caching strategy: Network-first with timeout
  if (isHTML) {
    event.respondWith(
      Promise.race([
        fetch(request).then((response) => {
          if (response.ok) {
            const responseClone = response.clone();
            caches.open(DYNAMIC_CACHE).then((cache) => {
              cache.put(request, responseClone);
            }).catch((err) => {
              console.warn('[SW] Failed to cache HTML response:', err);
            });
          }
          return response;
        }),
        new Promise((resolve, reject) =>
          setTimeout(() => reject(new Error('Network timeout')), 3000)
        )
      ]).catch(() => {
        return caches.match(request).then((cached) => {
          return cached || new Response('Offline - content not available', {
            status: 503,
            statusText: 'Service Unavailable',
            headers: new Headers({ 'Content-Type': 'text/html' })
          });
        });
      })
    );
    return;
  }

  // Default strategy: Network-first with cache fallback
  event.respondWith(
    fetch(request)
      .then((response) => {
        if (response.ok) {
          const responseToCache = response.clone();
          caches.open(DYNAMIC_CACHE).then((cache) => {
            cache.put(request, responseToCache);
          });
        }
        return response;
      })
      .catch(() => {
        return caches.match(request).then((cached) => {
          return cached || new Response('Offline - content not available', {
            status: 503,
            statusText: 'Service Unavailable',
            headers: new Headers({ 'Content-Type': 'text/plain' })
          });
        });
      })
  );
});

/**
 * Limit cache size by removing oldest entries
 * @param {string} cacheName - Name of the cache to limit
 * @param {number} maxSize - Maximum number of entries allowed
 */
async function limitCacheSize(cacheName, maxSize) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length > maxSize) {
    // Remove oldest entries (first ones in the list)
    const toDelete = keys.slice(0, keys.length - maxSize);
    await Promise.all(toDelete.map(key => cache.delete(key)));
    console.log(`[SW] Cleaned ${toDelete.length} entries from ${cacheName}`);
  }
}

// Listen for messages from the client
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }

  if (event.data && event.data.type === 'CLEAR_CACHE') {
    event.waitUntil(
      caches.keys().then((cacheNames) => {
        return Promise.all(
          cacheNames.map((cacheName) => {
            if (cacheName.startsWith('wtfun-')) {
              return caches.delete(cacheName);
            }
          })
        );
      }).then(() => {
        return self.clients.matchAll();
      }).then((clients) => {
        clients.forEach(client => client.postMessage({ type: 'CACHE_CLEARED' }));
      })
    );
  }

  // Prefetch images for upcoming content
  if (event.data && event.data.type === 'PREFETCH_IMAGES') {
    const images = event.data.images || [];
    if (images.length > 0) {
      event.waitUntil(
        caches.open(IMAGE_CACHE).then((cache) => {
          return Promise.allSettled(
            images.map(url => {
              return cache.match(url).then(cached => {
                if (!cached) {
                  return fetch(url).then(response => {
                    if (response.ok) {
                      const headers = new Headers(response.headers);
                      headers.append('sw-cached-date', new Date().toISOString());
                      return cache.put(url, new Response(response.body, {
                        status: response.status,
                        statusText: response.statusText,
                        headers: headers
                      }));
                    }
                  }).catch(() => {});
                }
              });
            })
          );
        }).then(() => {
          // Limit image cache size after prefetching
          return limitCacheSize(IMAGE_CACHE, MAX_IMAGE_CACHE_SIZE);
        })
      );
    }
  }

  // Get cache statistics
  if (event.data && event.data.type === 'GET_CACHE_STATS') {
    event.waitUntil(
      Promise.all([
        caches.open(STATIC_CACHE).then(c => c.keys()).then(k => k.length),
        caches.open(DYNAMIC_CACHE).then(c => c.keys()).then(k => k.length),
        caches.open(IMAGE_CACHE).then(c => c.keys()).then(k => k.length),
        caches.open(FONT_CACHE).then(c => c.keys()).then(k => k.length)
      ]).then(([staticCount, dynamicCount, imageCount, fontCount]) => {
        event.source.postMessage({
          type: 'CACHE_STATS',
          stats: {
            static: staticCount,
            dynamic: dynamicCount,
            images: imageCount,
            fonts: fontCount,
            version: CACHE_VERSION
          }
        });
      })
    );
  }
});

