/* --- 8. MODAL STYLES (Original) --- */
.modal-overlay {
    display: none;
    opacity: 0;
    transition: opacity 0.3s ease;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.6);
    z-index: 1000;
    justify-content: center;
    align-items: center;
    pointer-events: none;
}
.modal-overlay.active {
    display: flex;
    opacity: 1;
    pointer-events: auto;
}

/* Ensure modals appear above presentation view when both are active */
.presentation-fullpage.active ~ .modal-overlay.active,
body.presentation-active .modal-overlay.active {
    z-index: 1100;
}

/* --- Presentation Full Page View --- */
.presentation-fullpage {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    /* Transparent background to show the canvas animation behind */
    background: transparent;
    z-index: 1000;
    justify-content: center;
    align-items: stretch;
}

/* Background canvas for presentation view */
.presentation-bg-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
    display: block;
    /* Fallback background in case WebGL fails */
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.presentation-fullpage.active {
    display: flex;
}
.presentation-fullpage .presentation-content {
    width: 100%;
    height: 100%;
    max-width: none;
    border-radius: 0;
    box-shadow: none;
    background: transparent;
}

/* Semi-transparent header in fullpage presentation mode */
.presentation-fullpage .presentation-header {
    background-color: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

