    padding: 1px 5px;
    border-radius: 8px;
    min-width: 16px;
    text-align: center;
}

@keyframes emoji-pop {
    0% {
        transform: scale(0.8);
        opacity: 0;
    }
    50% {
        transform: scale(1.1);
    }
    100% {
        transform: scale(1);
        opacity: 1;
    }
}

/* Ranking summary emoji styles */
.ranking-summary-emoji {
