}

/* --- ADD TO END of style.css --- */

/* New status text overlay */
#scene-status-text {
    position: absolute;
    bottom: 10px;
    left: 10px;
    background-color: rgba(0, 0, 0, 0.7);
    color: white;
    padding: 8px 12px;
