/* Dashboard wrapper specific styles */
#dashboard-wrapper {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

#dashboard-wrapper header {
    margin-bottom: 20px;
}

#dashboard-wrapper h1 {
    color: #1a1a2e;
    font-size: 1.8em;
}

#dashboard-wrapper h2 {
    color: #374151;
    font-size: 1.3em;
    margin-top: 24px;
    margin-bottom: 16px;
}

#dashboard-wrapper main {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

/* Store Settings Form Styles */
.store-settings-form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.settings-section {
    background: #f9f9f9;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 20px;
}

.settings-section h3 {
    margin: 0 0 16px 0;
    font-size: 1.1em;
    color: #1a1a2e;
    border-bottom: 1px solid #e0e0e0;
    padding-bottom: 8px;
}

.form-group {
    margin-bottom: 16px;
}

.form-group:last-child {
    margin-bottom: 0;
}

.form-group label {
    display: block;
    margin-bottom: 6px;
    font-weight: 600;
    color: #374151;
    font-size: 0.95em;
}

.form-group input[type="text"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 1em;
    font-family: inherit;
    background: white;
    transition: border-color 0.2s, box-shadow 0.2s;
    box-sizing: border-box;
}

.form-group input[type="text"]:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 80px;
}

.form-group small {
    display: block;
    margin-top: 4px;
    font-size: 0.85em;
    color: #6b7280;
}

.checkbox-group {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 6px;
    font-weight: normal;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

.form-actions {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px 0;
}

.btn-primary {
    background-color: #3b82f6;
    color: white;
    padding: 12px 24px;
    border: none;
    border-radius: 6px;
    font-size: 1em;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s;
}

.btn-primary:hover {
    background-color: #2563eb;
}

.btn-primary:disabled {
    background-color: #9ca3af;
    cursor: not-allowed;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
    padding: 10px 15px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 1em;
    transition: background-color 0.2s;
}

.btn-danger:hover {
    background-color: #bb2d3b;
}

.btn-danger:disabled {
    background-color: #9ca3af;
    cursor: not-allowed;
}

.status-message {
    font-size: 0.9em;
    color: #666;
}

.admin-tools-section {
    margin-top: 8px;
}

.admin-tools-section h3 {
    color: #dc3545;
}

/* Responsive adjustments for store settings */
@media (max-width: 768px) {
    .settings-section {
        padding: 16px;
    }

    .checkbox-group {
        flex-direction: column;
        gap: 8px;
    }

    .form-actions {
        flex-direction: column;
        align-items: flex-start;
    }
}

/* ==============================================
   PLAN MENU DROPDOWN (Event Plan Hamburger Menu)
   ============================================== */

/* Event plan header row layout */
.event-plan-header-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 10px;
}

.event-plan-header-row .event-name-group {
    flex: 1;
    min-width: 0;
}

/* Container positioning for the plan menu in event panel header */
#share-menu-container {
    position: relative;
    flex-shrink: 0;
}

/* Plan menu dropdown extends hamburger dropdown */
#share-menu-dropdown.plan-menu-dropdown {
    position: absolute;
    top: 100%;
    /* Default: position dropdown to extend leftward from the button's right edge */
    left: auto;
    right: 0;
    margin-top: 8px;
    max-height: 80vh;
    overflow-y: auto;
    min-width: 220px;
    max-width: 280px;
    box-sizing: border-box;
}

/* On viewports where the right sidebar is constrained, ensure dropdown stays visible */
@media (max-width: 1400px) {
    #share-menu-dropdown.plan-menu-dropdown {
        min-width: 200px;
        max-width: min(280px, calc(100vw - 20px));
    }
}

/* Section labels for organizing menu items */
.plan-menu-section-label {
    padding: 10px 18px 6px;
    font-size: 0.75em;
    font-weight: 600;
    color: #6c757d;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Danger styling for destructive actions */
.plan-menu-danger {
    color: #dc3545 !important;
}

.plan-menu-danger:hover {
    background-color: #fff5f5 !important;
}

.plan-menu-danger .menu-item-icon {
    color: #dc3545;
}

/* Mobile: Ensure plan menu dropdown fits within viewport */
@media (max-width: 480px) {
    #share-menu-dropdown.plan-menu-dropdown {
        min-width: 200px;
        max-width: calc(100vw - 40px);
    }
}

/* Sessions List Modal */
.sessions-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10000;
    animation: fadeIn 0.2s ease-out;
}

.sessions-modal {
    background: white;
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
    max-width: 600px;
    width: 90%;
    max-height: 80vh;
    display: flex;
    flex-direction: column;
    animation: slideUp 0.3s ease-out;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.sessions-modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 20px;
    border-bottom: 1px solid #e9ecef;
}

.sessions-modal-header h3 {
    margin: 0;
    font-size: 1.2em;
    color: #333;
}

.sessions-modal-close {
    background: none;
    border: none;
    font-size: 1.5em;
    color: #6c757d;
    cursor: pointer;
    padding: 4px 8px;
    line-height: 1;
    border-radius: 4px;
    transition: all 0.2s;
}

.sessions-modal-close:hover {
    background-color: #f8f9fa;
    color: #333;
}

.sessions-modal-body {
    padding: 12px;
    overflow-y: auto;
    flex: 1;
}

.sessions-modal-actions {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e9ecef;
    justify-content: flex-end;
}

/* Session list items */
.sessions-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.session-list-item {
    display: flex;
    align-items: center;
    padding: 12px 16px;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
    background: white;
}

.session-list-item:hover {
    background-color: #f8f9fa;
    border-color: #007bff;
}

.session-list-item.selected {
    background-color: #e7f3ff;
    border-color: #007bff;
}

.session-list-item.current-session {
    border-color: #28a745;
    background-color: #f0fff4;
}

.session-list-checkbox {
    margin-right: 12px;
    width: 18px;
    height: 18px;
    cursor: pointer;
}

.session-list-info {
    flex: 1;
    min-width: 0;
}

.session-list-name {
    font-weight: 500;
    color: #333;
    margin-bottom: 4px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.session-list-meta {
    font-size: 0.85em;
    color: #6c757d;
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
}

.session-list-meta span {
    display: flex;
    align-items: center;
    gap: 4px;
}

.session-list-actions {
    display: flex;
    gap: 4px;
}

.session-action-btn {
    background: none;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 6px 10px;
    cursor: pointer;
    font-size: 0.85em;
    transition: all 0.2s;
    color: #495057;
}

.session-action-btn:hover {
    background-color: #f8f9fa;
    border-color: #adb5bd;
}

.session-action-btn.btn-danger {
    color: #dc3545;
    border-color: #dc3545;
}

.session-action-btn.btn-danger:hover {
    background-color: #fff5f5;
}

.session-action-btn.btn-primary {
    color: white;
    background-color: #007bff;
    border-color: #007bff;
}

.session-action-btn.btn-primary:hover {
    background-color: #0056b3;
}

/* Bulk actions bar */
.bulk-actions-bar {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background-color: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 12px;
}

.bulk-select-all {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    font-size: 0.9em;
    color: #495057;
}

.bulk-select-all input {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

.bulk-actions-buttons {
    display: flex;
    gap: 8px;
    margin-left: auto;
}

.sessions-empty-state {
    text-align: center;
    padding: 40px 20px;
    color: #6c757d;
}

.sessions-empty-state p {
    margin: 0;
    font-size: 0.95em;
}

/* Confirmation dialog */
.confirm-dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10001;
}

.confirm-dialog {
    background: white;
    border-radius: 12px;
    padding: 24px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.confirm-dialog h4 {
    margin: 0 0 12px 0;
    color: #333;
}

.confirm-dialog p {
    margin: 0 0 20px 0;
    color: #6c757d;
    line-height: 1.5;
}

.confirm-dialog-actions {
    display: flex;
    gap: 12px;
    justify-content: flex-end;
}

.confirm-dialog .btn-cancel {
    background-color: #f8f9fa;
    border: 1px solid #dee2e6;
    color: #495057;
    padding: 10px 20px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.95em;
    transition: all 0.2s;
}

.confirm-dialog .btn-cancel:hover {
    background-color: #e9ecef;
}

.confirm-dialog .btn-confirm {
    background-color: #dc3545;
    border: none;
    color: white;
    padding: 10px 20px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.95em;
    transition: all 0.2s;
}

.confirm-dialog .btn-confirm:hover {
    background-color: #bb2d3b;
}

.confirm-dialog .btn-confirm.btn-primary {
    background-color: #007bff;
}

.confirm-dialog .btn-confirm.btn-primary:hover {
    background-color: #0056b3;
}

/* --- Netlify Identity Widget z-index override --- */
/* Ensure the Netlify Identity popup appears above our user modal (z-index: 1000) */
.netlify-identity-widget,
#netlify-identity-widget,
.netlify-identity-page,
[class*="netlify-identity"] {
    z-index: 100000 !important;
}

/* The Netlify Identity modal wrapper - React Modal classes used by Netlify Identity */
.ReactModal__Overlay,
.ReactModalPortal,
.ReactModal__Content {
    z-index: 100000 !important;
}

/* Backdrop for Netlify Identity modal */
.ReactModal__Overlay--after-open {
    z-index: 99999 !important;
}

/* Ensure the actual modal content is above backdrop */
.ReactModal__Content--after-open {
    z-index: 100001 !important;
}

/* === AI-SOURCED CARD STYLES === */
/* Visual styling for AI-generated/discovered catalog items */

.ai-sourced-card {
    border: 2px solid #3498db !important;
    background: linear-gradient(135deg, rgba(52, 152, 219, 0.05) 0%, rgba(52, 152, 219, 0.1) 100%);
    box-shadow: 0 2px 8px rgba(52, 152, 219, 0.2);
}

.ai-sourced-card:hover {
    box-shadow: 0 4px 16px rgba(52, 152, 219, 0.35);
    border-color: #2980b9 !important;
}

/* AI Discovery Badge */
.ai-discovery-badge {
    position: absolute;
    top: 10px;
    left: 10px;
    background: linear-gradient(135deg, #3498db, #2980b9);
    color: white;
    padding: 4px 10px;
    border-radius: 12px;
    font-size: 0.75em;
    font-weight: 600;
    z-index: 10;
    display: flex;
    align-items: center;
    gap: 4px;
    box-shadow: 0 2px 6px rgba(52, 152, 219, 0.4);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.ai-discovery-badge::before {
    content: '✨';
    font-size: 0.9em;
}

/* Image Source Indicator - shows where AI item images came from */
.image-source-indicator {
    position: absolute;
    bottom: 10px;
    left: 10px;
    padding: 3px 8px;
    border-radius: 4px;
    font-size: 0.7em;
    font-weight: 600;
    z-index: 10;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    backdrop-filter: blur(4px);
    transition: opacity 0.3s ease;
}

.image-source-indicator.source-found {
    background: linear-gradient(135deg, rgba(39, 174, 96, 0.9), rgba(30, 132, 73, 0.9));
    color: white;
    box-shadow: 0 2px 6px rgba(39, 174, 96, 0.4);
}

.image-source-indicator.source-placeholder {
    background: linear-gradient(135deg, rgba(149, 165, 166, 0.9), rgba(127, 140, 141, 0.9));
    color: white;
    box-shadow: 0 2px 6px rgba(149, 165, 166, 0.4);
}

/* Image loading status overlay */
.image-loading-status {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.5);
    z-index: 15;
    transition: opacity 0.3s ease;
}

.image-loading-status .loading-spinner {
    width: 30px;
    height: 30px;
    border: 3px solid rgba(255, 255, 255, 0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    margin-bottom: 8px;
}

.image-loading-status .status-text {
    color: white;
    font-size: 0.75em;
    text-align: center;
    padding: 0 10px;
    max-width: 90%;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

.image-loading-status.loaded {
    opacity: 0;
    pointer-events: none;
}

/* AI Grouping Card (parent container for AI-generated category results) */
.ai-sourced-card.ai-grouping-card {
    background: linear-gradient(135deg, rgba(52, 152, 219, 0.08) 0%, rgba(155, 89, 182, 0.08) 100%);
    border: 2px solid #9b59b6 !important;
}

.ai-sourced-card.ai-grouping-card:hover {
    box-shadow: 0 4px 16px rgba(155, 89, 182, 0.35);
    border-color: #8e44ad !important;
}

.ai-grouping-badge {
    position: absolute;
    top: 10px;
    left: 10px;
    background: linear-gradient(135deg, #9b59b6, #8e44ad);
    color: white;
    padding: 4px 10px;
    border-radius: 12px;
    font-size: 0.75em;
    font-weight: 600;
    z-index: 10;
    display: flex;
    align-items: center;
    gap: 4px;
    box-shadow: 0 2px 6px rgba(155, 89, 182, 0.4);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.ai-grouping-badge::before {
    content: '🤖';
    font-size: 0.9em;
}

/* === SMART REFINEMENT CHIPS === */
/* Clickable suggestion chips below the search bar */

#ai-refinement-chips-container {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 10px 0;
    margin-top: 8px;
}

#ai-refinement-chips-container:empty {
    display: none;
}

.ai-refinement-chip {
    background: linear-gradient(135deg, rgba(52, 152, 219, 0.1), rgba(52, 152, 219, 0.2));
    border: 1px solid #3498db;
    color: #2980b9;
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 0.85em;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 4px;
}

.ai-refinement-chip::before {
    content: '🔍';
    font-size: 0.85em;
}

.ai-refinement-chip:hover {
    background: linear-gradient(135deg, #3498db, #2980b9);
    color: white;
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(52, 152, 219, 0.3);
}

.ai-refinement-chip:active {
    transform: translateY(0);
}

/* AI Child Items Container (for grouping results) */
.ai-children-container {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 15px;
    padding: 15px;
    margin-top: 10px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 8px;
}

/* Responsive adjustments for AI cards */
@media (max-width: 768px) {
    #ai-refinement-chips-container {
        padding: 8px 0;
        gap: 6px;
    }

    .ai-refinement-chip {
        padding: 5px 12px;
        font-size: 0.8em;
    }

    .ai-discovery-badge,
    .ai-grouping-badge {
        padding: 3px 8px;
        font-size: 0.7em;
    }

    .ai-children-container {
        grid-template-columns: 1fr;
        padding: 10px;
    }
}

/* === HYBRID SEARCH RESULT CAROUSELS === */
/* Styles for the combined catalog + AI search results display */

.search-result-carousel-section {
    margin-bottom: 30px;
    padding: 15px 0;
}

.search-result-carousel-section.catalog-results-section {
    border-bottom: 1px solid #e0e0e0;
    padding-bottom: 25px;
}

.search-result-carousel-section.ai-results-section {
    background: linear-gradient(135deg, rgba(52, 152, 219, 0.03) 0%, rgba(155, 89, 182, 0.05) 100%);
    border-radius: 12px;
    padding: 15px;
    margin-top: 20px;
}

.search-carousel-header {
    margin-bottom: 15px;
}

.search-carousel-title-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.search-carousel-title {
    font-size: 1.2em;
    font-weight: 600;
    margin: 0;
    color: #333;
}

.search-carousel-count {
    font-size: 0.85em;
    color: #666;
    background: #f0f0f0;
    padding: 3px 10px;
    border-radius: 12px;
}

.search-carousel-subtitle {
    font-size: 0.9em;
    color: #888;
    margin: 5px 0 0 0;
}

/* AI Badge for search results */
.search-carousel-header .ai-badge,
.ai-loading-header .ai-badge {
    background: linear-gradient(135deg, #3498db, #9b59b6);
    color: white;
    padding: 4px 12px;
    border-radius: 12px;
    font-size: 0.75em;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.search-carousel-wrapper {
    position: relative;
}

.search-carousel-container {
    display: flex;
    gap: 20px;
    overflow-x: auto;
    scroll-behavior: smooth;
    padding: 10px 5px;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
    scrollbar-color: #ccc transparent;
}

.search-carousel-container::-webkit-scrollbar {
    height: 6px;
}

.search-carousel-container::-webkit-scrollbar-track {
    background: transparent;
}

.search-carousel-container::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 3px;
}

.search-carousel-container .event-card {
    flex: 0 0 auto;
    width: 280px;
    min-width: 280px;
}

/* Navigation buttons for search carousels */
.search-carousel-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 36px;
    height: 36px;
    background: rgba(255, 255, 255, 0.95);
    border: 1px solid #ddd;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1em;
    color: #333;
    z-index: 10;
    transition: all 0.2s ease;
    display: none; /* Hidden by default, shown when has-overflow */
}

.search-carousel-wrapper.has-overflow .search-carousel-nav {
    display: flex;
    align-items: center;
    justify-content: center;
}

.search-carousel-nav.left {
    left: -10px;
}

.search-carousel-nav.right {
    right: -10px;
}

.search-carousel-nav:hover {
    background: #f0f0f0;
    border-color: #ccc;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

/* AI Loading Section */
.ai-loading-section {
    padding: 25px;
    background: linear-gradient(135deg, rgba(52, 152, 219, 0.03) 0%, rgba(155, 89, 182, 0.05) 100%);
