/**
 * Mobile-friendly Debug Panel Module
 * Provides a visual debug panel for debugging on any device
 *
 * Logs persist across page navigations within the same browser session
 * using sessionStorage, making it easier to track flows across views.
 *
 * Usage:
 *   import { initDebugPanel, debugLog } from '/utils/debug-panel.js';
 *   initDebugPanel(); // Call once on page load
 *   debugLog('Action description', { any: 'data' }, 'info'); // Log entries
 *
 * Types: 'info', 'success', 'error', 'data'
 */

const STORAGE_KEY = 'wtfun_debug_logs';
const MAX_PERSISTED_LOGS = 500; // Limit stored logs to prevent storage bloat

let debugLogs = [];
let debugPanel = null;
let debugToggle = null;
let debugLogContent = null;
let isInitialized = false;

/**
 * Load persisted debug logs from sessionStorage
 */
function loadPersistedLogs() {
    try {
        const stored = sessionStorage.getItem(STORAGE_KEY);
        if (stored) {
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
                return parsed;
            }
        }
    } catch (e) {
        console.warn('[Debug Panel] Failed to load persisted logs:', e);
    }
    return [];
}

/**
 * Save debug logs to sessionStorage
 */
function persistLogs() {
    try {
        // Keep only the most recent logs to prevent storage overflow
        const logsToStore = debugLogs.slice(-MAX_PERSISTED_LOGS);
        sessionStorage.setItem(STORAGE_KEY, JSON.stringify(logsToStore));
    } catch (e) {
        console.warn('[Debug Panel] Failed to persist logs:', e);
    }
}

/**
 * Render a single log entry to the panel
 * @param {Object} entry - Log entry with timestamp, action, data, type
 * @param {boolean} isPersisted - Whether this is a log from a previous page
 */
function renderLogEntry(entry, isPersisted = false) {
    if (!debugLogContent) return;

    const entryEl = document.createElement('div');
    entryEl.className = 'debug-entry' + (isPersisted ? ' debug-entry-persisted' : '');

    let dataClass = '';
    if (entry.type === 'error') dataClass = 'debug-error';
    else if (entry.type === 'success') dataClass = 'debug-success';

    let html = `<div class="debug-timestamp">${entry.timestamp}</div>`;
    html += `<div class="debug-action ${dataClass}">[${entry.type.toUpperCase()}] ${escapeHtml(entry.action)}</div>`;

    if (entry.data !== null && entry.data !== undefined) {
        const dataStr = typeof entry.data === 'object' ? JSON.stringify(entry.data, null, 2) : String(entry.data);
        html += `<div class="debug-data">${escapeHtml(dataStr)}</div>`;
    }

    entryEl.innerHTML = html;
    debugLogContent.appendChild(entryEl);
}

/**
 * Render all persisted logs from sessionStorage
 */
function renderPersistedLogs() {
    if (!debugLogContent || debugLogs.length === 0) return;

    // Add a separator to show these are from previous pages
    const separator = document.createElement('div');
    separator.className = 'debug-separator';
    separator.innerHTML = `<span>--- Logs from previous pages (${debugLogs.length} entries) ---</span>`;
    debugLogContent.appendChild(separator);

    // Render each persisted log
    for (const entry of debugLogs) {
        renderLogEntry(entry, true);
    }

    // Add another separator
    const endSeparator = document.createElement('div');
    endSeparator.className = 'debug-separator';
    endSeparator.innerHTML = '<span>--- Current page logs below ---</span>';
    debugLogContent.appendChild(endSeparator);

    // Scroll to bottom
    debugPanel.scrollTop = debugPanel.scrollHeight;
}

/**
 * Escape HTML for safe display
 */
function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

/**
 * Initialize the debug panel by injecting HTML and setting up event listeners
 * @param {string} title - Optional title for the debug panel (default: 'Debug Log')
 */
export function initDebugPanel(title = 'Debug Log') {
    if (isInitialized) {
        console.warn('[Debug Panel] Already initialized');
        return;
    }

    // Load any persisted logs from previous pages in this session
    debugLogs = loadPersistedLogs();

    // Inject CSS if not already present
    if (!document.querySelector('link[href*="debug-panel.css"]')) {
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = '/css/debug-panel.css';
        document.head.appendChild(link);
    }

    // DORMANT FEATURE: Debug Toggle Button - hidden until debug functionality is fully utilized
    // TODO: Re-enable the floating debug toggle button when debug features are needed
    // The debug panel infrastructure is preserved for internal debugging but the UI toggle is hidden
    /*
    // Create debug toggle button
    debugToggle = document.createElement('button');
    debugToggle.id = 'debugToggle';
    debugToggle.className = 'debug-toggle';
    debugToggle.title = 'Toggle Debug Panel';
    debugToggle.textContent = '🔧';
    document.body.appendChild(debugToggle);
    */

    // Create debug panel (hidden, can be accessed programmatically if needed)
    debugPanel = document.createElement('div');
    debugPanel.id = 'debugPanel';
    debugPanel.className = 'debug-panel';
    debugPanel.innerHTML = `
        <div class="debug-panel-header">
            <span class="debug-panel-title">📋 ${escapeHtml(title)}</span>
            <div class="debug-panel-controls">
                <button class="debug-btn" id="clearDebugLog">Clear</button>
                <button class="debug-btn" id="closeDebugPanel">✕</button>
            </div>
        </div>
        <div id="debugLogContent"></div>
    `;
    document.body.appendChild(debugPanel);

    // Get content container
    debugLogContent = document.getElementById('debugLogContent');

    // Set up event listeners (panel can still be controlled programmatically)
    // DORMANT: debugToggle event listener removed since button is hidden
    // if (debugToggle) {
    //     debugToggle.addEventListener('click', toggleDebugPanel);
    // }
    document.getElementById('closeDebugPanel').addEventListener('click', () => {
        debugPanel.classList.remove('visible');
    });
    document.getElementById('clearDebugLog').addEventListener('click', clearDebugLogs);

    isInitialized = true;

    // Render any persisted logs from previous pages
    if (debugLogs.length > 0) {
        renderPersistedLogs();
        // DORMANT: Toggle button indicator removed since button is hidden
        // debugToggle.classList.add('has-logs');
    }

    // Log initialization with page context
    debugLog('Debug panel initialized', {
        page: window.location.pathname,
        search: window.location.search,
        persistedLogCount: debugLogs.length - 1, // -1 because we're about to add this entry
        timestamp: Date.now()
    }, 'info');
}

/**
 * Add a debug log entry to the panel
 * @param {string} action - The action description
 * @param {any} data - Optional data to display
 * @param {string} type - 'info', 'success', 'error', 'data'
 */
export function debugLog(action, data = null, type = 'info') {
    const timestamp = new Date().toISOString();
    const entry = { timestamp, action, data, type };

    // Store the log entry
    debugLogs.push(entry);

    // Persist to sessionStorage so logs survive page navigation
    persistLogs();

    // If not initialized, logs will be rendered when panel initializes
    if (!isInitialized) {
        return;
    }

    // DORMANT: Visual indicator for toggle button is disabled since button is hidden
    // Add visual indicator if panel is closed
    // if (debugToggle && !debugPanel.classList.contains('visible')) {
    //     debugToggle.classList.add('has-logs');
    // }

    // Render the entry to the panel
    renderLogEntry(entry, false);

    // Auto-scroll to bottom
    debugPanel.scrollTop = debugPanel.scrollHeight;
}

/**
 * Toggle debug panel visibility
 */
export function toggleDebugPanel() {
    if (!debugPanel) return;

    debugPanel.classList.toggle('visible');
    // DORMANT: Toggle button class update disabled since button is hidden
    // if (debugToggle && debugPanel.classList.contains('visible')) {
    //     debugToggle.classList.remove('has-logs');
    // }
}

/**
 * Clear all debug logs
 */
export function clearDebugLogs() {
    debugLogs = [];
    if (debugLogContent) {
        debugLogContent.innerHTML = '';
    }
    // Also clear sessionStorage
    try {
        sessionStorage.removeItem(STORAGE_KEY);
    } catch (e) {
        console.warn('[Debug Panel] Failed to clear persisted logs:', e);
    }
    debugLog('Debug log cleared', null, 'info');
}

/**
 * Get all debug logs
 * @returns {Array} Array of debug log entries
 */
export function getDebugLogs() {
    return [...debugLogs];
}

/**
 * Check if debug panel is initialized
 * @returns {boolean}
 */
export function isDebugPanelInitialized() {
    return isInitialized;
}

// Auto-initialize if the script is loaded and DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        // Don't auto-init, let pages call initDebugPanel explicitly
    });
}

// Export for use as a module
export default {
    initDebugPanel,
    debugLog,
    toggleDebugPanel,
    clearDebugLogs,
    getDebugLogs,
    isDebugPanelInitialized
};

let isDebugMode = false;

export function setDebugMode(enabled) {
    isDebugMode = enabled;
}

export function log(prefix, ...args) {
    if (isDebugMode) {
        console.log(`[${prefix}]`, ...args);
    }
}

// Image optimization utility using Netlify Image CDN
// Provides optimized image URLs with automatic format conversion and sizing

// Device pixel ratio detection for responsive images
const DPR = typeof window !== 'undefined' ? Math.min(window.devicePixelRatio || 1, 2) : 1;

/**
 * Check if a Cloudinary URL already has transformations
 * @param {string} url - The Cloudinary URL to check
 * @returns {boolean} True if transformations exist
 */
export function hasCloudinaryTransformations(url) {
  if (!url || !url.includes('/upload/')) return false;
  const uploadIndex = url.indexOf('/upload/');
  const afterUpload = url.slice(uploadIndex + 8);
  // Cloudinary transformation patterns start with letter_value (e.g., c_fill, w_600)
  return /^[a-z]_[^/]+/.test(afterUpload);
}

/**
 * Apply Cloudinary transformations to a URL, avoiding duplicates
 * @param {string} url - The Cloudinary URL
 * @param {string} transformations - The transformations to apply (e.g., "c_fill,w_300")
 * @returns {string} URL with transformations applied
 */
export function applyCloudinaryTransform(url, transformations) {
  if (!url || !url.includes('cloudinary') || !url.includes('/upload/')) return url;

  const uploadIndex = url.indexOf('/upload/');

  // Check if URL already has transformations
  if (hasCloudinaryTransformations(url)) {
    // Prepend new transformations before existing ones (Cloudinary chains transformations)
    return url.slice(0, uploadIndex + 8) + transformations + '/' + url.slice(uploadIndex + 8);
  }

  // No existing transformations, add them normally
  return url.slice(0, uploadIndex + 8) + transformations + '/' + url.slice(uploadIndex + 8);
}

/**
 * Get the base Cloudinary URL without any transformations
 * Useful for passing clean URLs to Netlify Image CDN
 * @param {string} url - The Cloudinary URL
 * @returns {string} Base URL without transformations
 */
export function getBaseCloudinaryUrl(url) {
  if (!url || !url.includes('cloudinary') || !url.includes('/upload/')) return url;

  const uploadIndex = url.indexOf('/upload/');
  const afterUpload = url.slice(uploadIndex + 8);

  // Check if there are transformations
  if (/^[a-z]_[^/]+/.test(afterUpload)) {
    // Find where the actual filename starts (after all transformation segments)
    // Cloudinary transformations are separated by / and the last segment before version (v123...) or filename is the last transform
    const segments = afterUpload.split('/');
    let filenameStartIndex = 0;

    for (let i = 0; i < segments.length; i++) {
      // Check if this segment looks like a transformation (starts with letter_something)
      if (/^[a-z]_/.test(segments[i]) || /^[a-z]:[^/]+/.test(segments[i])) {
        filenameStartIndex = i + 1;
      } else {
        break;
      }
    }

    // Reconstruct URL with base and filename parts only
    const baseUrl = url.slice(0, uploadIndex + 8);
    const filenamePart = segments.slice(filenameStartIndex).join('/');
    return baseUrl + filenamePart;
  }

  return url;
}

/**
 * Convert a Cloudinary or external image URL to use Netlify Image CDN
 * @param {string} imageUrl - The original image URL
 * @param {Object} options - Transformation options
 * @param {number} options.width - Target width in pixels
 * @param {number} options.height - Target height in pixels
 * @param {string} options.fit - How to fit image: 'contain', 'cover', 'fill'
 * @param {string} options.format - Output format: 'avif', 'webp', 'jpg', 'png', 'auto'
 * @param {number} options.quality - Quality 1-100 (default 75)
 * @param {boolean} options.useDPR - Whether to multiply dimensions by device pixel ratio (default true)
 * @returns {string} Optimized image URL via Netlify Image CDN
 */
export function optimizeImageUrl(imageUrl, options = {}) {
  if (!imageUrl) return imageUrl;

  // Skip if already using Netlify Image CDN
  if (imageUrl.includes('/.netlify/images')) {
    return imageUrl;
  }

  // For Cloudinary URLs, get the base URL without transformations to avoid double-transforming
  let cleanUrl = imageUrl;
  if (imageUrl.includes('res.cloudinary.com') && hasCloudinaryTransformations(imageUrl)) {
    cleanUrl = getBaseCloudinaryUrl(imageUrl);
  }

  // Build query parameters
  const params = new URLSearchParams();
  params.set('url', cleanUrl);

  // Apply DPR scaling for sharper images on high-res displays
  const useDPR = options.useDPR !== false;
  const scaleFactor = useDPR ? DPR : 1;

  if (options.width) params.set('w', Math.round(options.width * scaleFactor));
  if (options.height) params.set('h', Math.round(options.height * scaleFactor));
  if (options.fit) params.set('fit', options.fit);
  if (options.format) params.set('fm', options.format);
  if (options.quality) params.set('q', options.quality);

  return `/.netlify/images?${params.toString()}`;
}

/**
 * Get responsive image srcset using Netlify Image CDN
 * @param {string} imageUrl - The original image URL
 * @param {number[]} widths - Array of widths for srcset
 * @param {Object} options - Additional options (format, quality, fit)
 * @returns {string} srcset string for responsive images
 */
export function getResponsiveSrcset(imageUrl, widths = [320, 640, 960, 1280, 1920], options = {}) {
  if (!imageUrl) return '';

  return widths.map(width => {
    const url = optimizeImageUrl(imageUrl, { ...options, width, useDPR: false });
    return `${url} ${width}w`;
  }).join(', ');
}

/**
 * Get sizes attribute for responsive images
 * @param {Object} breakpoints - Breakpoint configuration
 * @returns {string} sizes attribute value
 */
export function getResponsiveSizes(breakpoints = {}) {
  const defaults = {
    mobile: '100vw',
    tablet: '50vw',
    desktop: '33vw',
    mobileMax: 768,
    tabletMax: 1024
  };
  const config = { ...defaults, ...breakpoints };

  return `(max-width: ${config.mobileMax}px) ${config.mobile}, (max-width: ${config.tabletMax}px) ${config.tablet}, ${config.desktop}`;
}

/**
 * Preload critical images using link preload
 * @param {string[]} imageUrls - Array of image URLs to preload
 * @param {Object} options - Optimization options
 */
export function preloadCriticalImages(imageUrls, options = {}) {
  const head = document.head;

  imageUrls.forEach(url => {
    const optimizedUrl = optimizeImageUrl(url, {
      width: options.width || 400,
      format: 'webp',
      quality: 80,
      ...options
    });

    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'image';
    link.href = optimizedUrl;
    link.type = 'image/webp';
    link.fetchPriority = 'high';
    head.appendChild(link);
  });
}

/**
 * Generate a blurhash placeholder URL
 * @param {string} imageUrl - The original image URL
 * @returns {string} Blurhash placeholder URL
 */
export function getBlurhashPlaceholder(imageUrl) {
  if (!imageUrl) return '';
  return optimizeImageUrl(imageUrl, { format: 'blurhash', width: 32, height: 32, useDPR: false });
}

/**
 * Check if we should use Netlify Image CDN for this URL
 * @param {string} imageUrl - The image URL to check
 * @returns {boolean} Whether to use Netlify Image CDN
 */
export function shouldUseNetlifyImageCDN(imageUrl) {
  if (!imageUrl) return false;

  // Use for Cloudinary images
  if (imageUrl.includes('res.cloudinary.com')) return true;

  // Use for local images
  if (imageUrl.startsWith('/') && !imageUrl.startsWith('//')) return true;

  return false;
}

/**
 * Create an optimized image element with lazy loading and responsive attributes
 * @param {string} imageUrl - The original image URL
 * @param {Object} options - Configuration options
 * @returns {HTMLImageElement} Configured image element
 */
export function createOptimizedImage(imageUrl, options = {}) {
  const {
    alt = '',
    width = 400,
    height,
    className = '',
    loading = 'lazy',
    decoding = 'async',
    fetchPriority,
    sizes,
    widths = [320, 640, 960, 1280]
  } = options;

  const img = document.createElement('img');

  // Set optimized src
  img.src = optimizeImageUrl(imageUrl, { width, height, format: 'webp', quality: 80 });

  // Add srcset for responsive images
  if (shouldUseNetlifyImageCDN(imageUrl)) {
    img.srcset = getResponsiveSrcset(imageUrl, widths, { format: 'webp', quality: 80 });
    img.sizes = sizes || getResponsiveSizes();
  }

  // Set attributes
  img.alt = alt;
  if (className) img.className = className;
  img.loading = loading;
  img.decoding = decoding;
  if (fetchPriority) img.fetchPriority = fetchPriority;

  // Add width and height to prevent layout shift
  if (width) img.width = width;
  if (height) img.height = height;

  return img;
}

/**
 * Prefetch images that will likely be needed soon
 * @param {string[]} imageUrls - Array of image URLs to prefetch
 */
export function prefetchImages(imageUrls) {
  if ('requestIdleCallback' in window) {
    requestIdleCallback(() => {
      imageUrls.forEach(url => {
        const link = document.createElement('link');
        link.rel = 'prefetch';
        link.as = 'image';
        link.href = optimizeImageUrl(url, { width: 400, format: 'webp', quality: 75 });
        document.head.appendChild(link);
      });
    }, { timeout: 3000 });
  }
}

// Lazy module loader for performance optimization
// This utility handles dynamic imports for heavy, infrequently used modules

const loadedModules = new Map();
const loadingPromises = new Map();

/**
 * Generic lazy loader with deduplication and caching
 * @param {string} moduleName - Name of the module for caching
 * @param {Function} importFn - Function that returns the import promise
 * @returns {Promise} Resolved module
 */
async function lazyLoad(moduleName, importFn) {
  // Return cached module if available
  if (loadedModules.has(moduleName)) {
    return loadedModules.get(moduleName);
  }

  // Return existing loading promise to avoid duplicate requests
  if (loadingPromises.has(moduleName)) {
    return loadingPromises.get(moduleName);
  }

  // Create loading promise
  const loadPromise = importFn()
    .then(module => {
      loadedModules.set(moduleName, module);
      loadingPromises.delete(moduleName);
      console.log(`[LazyLoader] ${moduleName} module loaded`);
      return module;
    })
    .catch(error => {
      loadingPromises.delete(moduleName);
      console.error(`[LazyLoader] Failed to load ${moduleName} module:`, error);
      throw error;
    });

  loadingPromises.set(moduleName, loadPromise);
  return loadPromise;
}

/**
 * Lazy load the chat module when needed
 */
export async function loadChatModule() {
  return lazyLoad('chat', () => import('../chat.js'));
}

/**
 * Lazy load the presentation view component
 */
export async function loadPresentationModule() {
  return lazyLoad('presentation', () => import('../components/presentation.js'));
}

/**
 * Lazy load the itinerary/scene builder component
 */
export async function loadItineraryModule() {
  return lazyLoad('itinerary', () => import('../components/itinerary.js'));
}

/**
 * Lazy load the calendar view component
 */
export async function loadCalendarModule() {
  return lazyLoad('calendar', () => import('../components/calendarView.js'));
}

/**
 * Lazy load third-party libraries with timeout and retry
 */
export async function loadSortableJS() {
  if (loadedModules.has('sortable')) {
    return loadedModules.get('sortable');
  }

  if (loadingPromises.has('sortable')) {
    return loadingPromises.get('sortable');
  }

  const loadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/sortablejs@1.15.0/Sortable.min.js';
    script.crossOrigin = 'anonymous';

    const timeout = setTimeout(() => {
      script.remove();
      loadingPromises.delete('sortable');
      reject(new Error('SortableJS load timeout'));
    }, 10000);

    script.onload = () => {
      clearTimeout(timeout);
      loadedModules.set('sortable', window.Sortable);
      loadingPromises.delete('sortable');
      console.log('[LazyLoader] SortableJS loaded');
      resolve(window.Sortable);
    };

    script.onerror = () => {
      clearTimeout(timeout);
      loadingPromises.delete('sortable');
      reject(new Error('SortableJS failed to load'));
    };

    document.head.appendChild(script);
  });

  loadingPromises.set('sortable', loadPromise);
  return loadPromise;
}

/**
 * Lazy load Flatpickr date picker
 */
export async function loadFlatpickr() {
  if (loadedModules.has('flatpickr')) {
    return loadedModules.get('flatpickr');
  }

  if (loadingPromises.has('flatpickr')) {
    return loadingPromises.get('flatpickr');
  }

  const loadPromise = new Promise((resolve, reject) => {
    // Load CSS first
    if (!document.querySelector('link[href*="flatpickr"]')) {
      const cssLink = document.createElement('link');
      cssLink.rel = 'stylesheet';
      cssLink.href = 'https://cdn.jsdelivr.net/npm/flatpickr/dist/flatpickr.min.css';
      cssLink.crossOrigin = 'anonymous';
      document.head.appendChild(cssLink);
    }

    // Load JS
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/flatpickr';
    script.crossOrigin = 'anonymous';

    const timeout = setTimeout(() => {
      script.remove();
      loadingPromises.delete('flatpickr');
      reject(new Error('Flatpickr load timeout'));
    }, 10000);

    script.onload = () => {
      clearTimeout(timeout);
      loadedModules.set('flatpickr', window.flatpickr);
      loadingPromises.delete('flatpickr');
      console.log('[LazyLoader] Flatpickr loaded');
      resolve(window.flatpickr);
    };

    script.onerror = () => {
      clearTimeout(timeout);
      loadingPromises.delete('flatpickr');
      reject(new Error('Flatpickr failed to load'));
    };

    document.head.appendChild(script);
  });

  loadingPromises.set('flatpickr', loadPromise);
  return loadPromise;
}

/**
 * Preload modules in idle time for faster subsequent access
 */
export function preloadModules() {
  if ('requestIdleCallback' in window) {
    requestIdleCallback(() => {
      console.log('[LazyLoader] Preloading modules during idle time...');
      // Preload less critical modules with lower priority
      loadChatModule().catch(() => {});
    }, { timeout: 5000 });

    // Preload calendar after a longer delay
    requestIdleCallback(() => {
      loadCalendarModule().catch(() => {});
    }, { timeout: 10000 });
  } else {
    // Fallback for browsers without requestIdleCallback
    setTimeout(() => {
      loadChatModule().catch(() => {});
    }, 3000);
    setTimeout(() => {
      loadCalendarModule().catch(() => {});
    }, 6000);
  }
}

/**
 * Check if a module is already loaded
 * @param {string} moduleName - Name of the module
 * @returns {boolean} Whether the module is loaded
 */
export function isModuleLoaded(moduleName) {
  return loadedModules.has(moduleName);
}

/**
 * Clear cached modules (useful for development/testing)
 */
export function clearModuleCache() {
  loadedModules.clear();
  loadingPromises.clear();
}

// FILE: utils/planStateSync.js
// Centralized plan state synchronization module
// Handles cross-view UI synchronization for event plan data

import { state } from '../state.js';
import { log } from './debug.js';
import { CONSTANTS } from '../config.js';

// Track pending updates to debounce rapid changes
let updateDebounceTimer = null;
const UPDATE_DEBOUNCE_MS = 50;

// Registered callbacks for different UI components
const syncCallbacks = {
    sidebar: null,
    presentation: null,
    catalog: null,
    hamburgerMenu: null,
    detailModal: null,
    wtfPlansPanel: null
};

// Debug mode flag for comprehensive logging
let debugMode = true;

/**
 * Enable or disable debug mode for sync operations
 * @param {boolean} enabled - Whether debug mode is enabled
 */
export function setDebugMode(enabled) {
    debugMode = enabled;
    console.log(`[PlanSync DEBUG] Debug mode ${enabled ? 'ENABLED' : 'DISABLED'}`);
}

/**
 * Log sync operation with debug prefix
 * @param {string} message - Message to log
 * @param {any} data - Optional data to include
 */
function debugLog(message, data = null) {
    if (debugMode) {
        if (data !== null) {
            console.log(`[PlanSync DEBUG] ${message}`, data);
        } else {
            console.log(`[PlanSync DEBUG] ${message}`);
        }
    }
    log('PlanSync', message);
}

/**
 * Register a callback for a specific UI component
 * @param {string} component - Component name ('sidebar', 'presentation', 'catalog', 'hamburgerMenu', 'detailModal')
 * @param {Function} callback - Callback function to invoke on sync events
 */
export function registerSyncCallback(component, callback) {
    if (syncCallbacks.hasOwnProperty(component)) {
        syncCallbacks[component] = callback;
        debugLog(`Registered callback for: ${component}`);
    } else {
        console.warn(`[PlanSync] Unknown component: ${component}`);
    }
}

/**
 * Unregister a callback for a specific UI component
 * @param {string} component - Component name
 */
export function unregisterSyncCallback(component) {
    if (syncCallbacks.hasOwnProperty(component)) {
        syncCallbacks[component] = null;
        debugLog(`Unregistered callback for: ${component}`);
    }
}

/**
 * Get current plan summary data for UI updates
 * @returns {Object} Plan summary with item count, total cost, date, etc.
 */
export function getPlanSummary() {
    const lockedItemsCount = state.cart.lockedItems.size;
    const ideasCount = state.cart.items.size;

    // Calculate total cost
    let totalCost = 0;
    let subtotal = 0;

    state.cart.lockedItems.forEach((itemInfo, recordId) => {
        const record = state.records.all.find(r => r.id === recordId);
        if (!record) return;

        // Get price - simplified calculation
        let unitPrice = itemInfo.overridePrice;
        if (unitPrice == null) {
            unitPrice = parseFloat(record.fields?.Price) || 0;
        }

        // Apply package discount if applicable
        if (itemInfo.packageId && state.session.activePackages) {
            const packageInfo = state.session.activePackages.get(itemInfo.packageId);
            if (packageInfo && packageInfo.discount > 0) {
                unitPrice = unitPrice * (1 - packageInfo.discount / 100);
            }
        }

        const quantity = parseInt(itemInfo.quantity) || 1;
        subtotal += unitPrice * quantity;
    });

    const amountReceived = state.session.user?.amountReceived || 0;
    totalCost = subtotal - amountReceived;

    // Get event date
    const eventDate = state.eventDetails.combined.get(CONSTANTS.DETAIL_TYPES.DATE);
    const eventName = state.eventDetails.combined.get(CONSTANTS.DETAIL_TYPES.EVENT_NAME);
    const goals = state.eventDetails.combined.get(CONSTANTS.DETAIL_TYPES.GOALS);
    const guestCount = state.eventDetails.combined.get(CONSTANTS.DETAIL_TYPES.GUEST_COUNT);

    const summary = {
        lockedItemsCount,
        ideasCount,
        totalItems: lockedItemsCount + ideasCount,
        subtotal,
        totalCost,
        amountReceived,
        eventDate,
        eventName,
        goals,
        guestCount,
        sessionId: state.session.id,
        isAuthenticated: state.session.user?.isAuthenticated || false
    };

    debugLog('Plan summary generated:', summary);
    return summary;
}

/**
 * Sync the plan state across all registered UI components
 * @param {string} source - The source component triggering the sync (to avoid loops)
 * @param {string} changeType - Type of change ('itemAdded', 'itemRemoved', 'itemUpdated', 'dateChanged', 'detailsChanged', 'fullRefresh')
 * @param {Object} changeData - Optional data about what changed
 */
export function syncPlanState(source, changeType = 'fullRefresh', changeData = {}) {
    debugLog(`========== SYNC TRIGGERED ==========`);
    debugLog(`Source: ${source}, ChangeType: ${changeType}`, changeData);
    debugLog(`Current lockedItems size: ${state.cart.lockedItems.size}`);
    debugLog(`Current eventDetails size: ${state.eventDetails.combined.size}`);

    // Debounce rapid updates
    if (updateDebounceTimer) {
        clearTimeout(updateDebounceTimer);
    }

    updateDebounceTimer = setTimeout(() => {
        const summary = getPlanSummary();

        // Notify all registered callbacks except the source
        Object.entries(syncCallbacks).forEach(([component, callback]) => {
            if (callback && component !== source) {
                try {
                    debugLog(`Notifying component: ${component}`);
                    callback(changeType, summary, changeData);
                } catch (error) {
                    console.error(`[PlanSync] Error notifying ${component}:`, error);
                }
            }
        });

        // Also dispatch a custom DOM event for components that prefer event listeners
        const event = new CustomEvent('planStateChanged', {
            detail: {
                source,
                changeType,
                summary,
                changeData
            }
        });
        document.dispatchEvent(event);
        debugLog(`Dispatched planStateChanged event`);
        debugLog(`========== SYNC COMPLETE ==========`);
    }, UPDATE_DEBOUNCE_MS);
}

/**
 * Force immediate sync without debouncing
 * @param {string} source - The source component
 * @param {string} changeType - Type of change
 * @param {Object} changeData - Change data
 */
export function syncPlanStateImmediate(source, changeType = 'fullRefresh', changeData = {}) {
    debugLog(`========== IMMEDIATE SYNC ==========`);
    debugLog(`Source: ${source}, ChangeType: ${changeType}`, changeData);

    const summary = getPlanSummary();

    Object.entries(syncCallbacks).forEach(([component, callback]) => {
        if (callback && component !== source) {
            try {
                debugLog(`Notifying component: ${component}`);
                callback(changeType, summary, changeData);
            } catch (error) {
                console.error(`[PlanSync] Error notifying ${component}:`, error);
            }
        }
    });

    const event = new CustomEvent('planStateChanged', {
        detail: {
            source,
            changeType,
            summary,
            changeData
        }
    });
    document.dispatchEvent(event);
    debugLog(`========== IMMEDIATE SYNC COMPLETE ==========`);
}

/**
 * Update the mobile summary bar (hamburger menu area) with current plan data
 */
export function updateMobileSummaryBar() {
    debugLog('Updating mobile summary bar...');

    const summary = getPlanSummary();

    const itemCountEl = document.getElementById('mobile-bar-item-count');
    const totalCostEl = document.getElementById('mobile-bar-total-cost');

    if (itemCountEl) {
        const count = summary.lockedItemsCount;
        itemCountEl.textContent = `${count} item${count !== 1 ? 's' : ''}`;
        debugLog(`Updated mobile item count: ${count}`);
    } else {
        debugLog('WARNING: mobile-bar-item-count element not found');
    }

    if (totalCostEl) {
        totalCostEl.textContent = `$${summary.totalCost.toFixed(2)}`;
        debugLog(`Updated mobile total cost: $${summary.totalCost.toFixed(2)}`);
    } else {
        debugLog('WARNING: mobile-bar-total-cost element not found');
    }
}

/**
 * Initialize plan state sync system
 * Sets up event listeners and performs initial sync
 */
export function initializePlanStateSync() {
    debugLog('Initializing plan state sync system...');

    // Listen for sessionReady to do initial sync
    document.addEventListener('sessionReady', () => {
        debugLog('sessionReady event received - triggering full sync');
        syncPlanStateImmediate('system', 'sessionLoaded', {});
        updateMobileSummaryBar();
    });

    // Listen for planStateChanged to update mobile bar
    document.addEventListener('planStateChanged', (e) => {
        updateMobileSummaryBar();
    });

    debugLog('Plan state sync system initialized');
}

// Export a helper to get sync status for debugging
export function getSyncStatus() {
    return {
        registeredCallbacks: Object.keys(syncCallbacks).filter(k => syncCallbacks[k] !== null),
        debugMode,
        currentPlanSummary: getPlanSummary()
    };
}

// FILE: utils/realtimeUpdates.js
// Phase 5: Real-time update handlers for Projects and Tasks
// Handles incoming Pusher events and updates UI accordingly

import { state, setState } from '../state.js';
import { log } from './debug.js';
import { subscribeToProject, unsubscribeFromProject, triggerProjectEvent, getPusherInstance } from '../pusher.js';
import { showToast } from '../ui.js';
import * as api from '../api.js';

// Track if real-time is initialized for the current project
let isInitialized = false;
let currentProjectId = null;

// Callback registry for component updates
const updateCallbacks = {
    taskManager: null,
    projectsDashboard: null
};

/**
 * Show a toast notification for real-time updates
 * @param {string} message - Message to display
 * @param {string} type - Type of notification (info, success, warning)
 */
function showRealtimeToast(message, type = 'info') {
    // Create a styled toast for real-time updates
    const toastContainer = document.getElementById('toast-notification');
    if (toastContainer) {
        // Add a specific class for real-time updates
        toastContainer.classList.add('realtime-toast');
        showToast(message, 4000);

        // Remove the class after animation
        setTimeout(() => {
            toastContainer.classList.remove('realtime-toast');
        }, 4500);
    } else {
        showToast(message, 4000);
    }
}

/**
 * Initialize real-time updates for a project
 * @param {string} projectId - The project ID to monitor
 * @param {Object} options - Configuration options
 */
export function initializeRealtimeUpdates(projectId, options = {}) {
    if (!projectId) {
        log('RealtimeUpdates', 'Cannot initialize - no project ID provided');
        return;
    }

    // Already initialized for this project
    if (isInitialized && currentProjectId === projectId) {
        log('RealtimeUpdates', `Already initialized for project: ${projectId}`);
        return;
    }

    // Wait for Pusher to be available
    if (!getPusherInstance()) {
        log('RealtimeUpdates', 'Pusher not initialized - waiting...');
        // Try again when Pusher is ready
        if (typeof window.waitForPusher === 'function') {
            window.waitForPusher().then(() => {
                initializeRealtimeUpdates(projectId, options);
            }).catch(err => {
                console.error('Failed to wait for Pusher:', err);
            });
        }
        return;
    }

    // Store callbacks
    if (options.onTaskUpdate) {
        updateCallbacks.taskManager = options.onTaskUpdate;
    }
    if (options.onProjectUpdate) {
        updateCallbacks.projectsDashboard = options.onProjectUpdate;
    }

    // Subscribe to project channel with event handlers
    subscribeToProject(projectId, {
        onTaskCreated: handleTaskCreated,
        onTaskUpdated: handleTaskUpdated,
        onTaskDeleted: handleTaskDeleted,
        onTaskReordered: handleTaskReordered,
        onProjectStatusChanged: handleProjectStatusChanged,
        onProjectUpdated: handleProjectUpdated,
        onItemAdded: handleItemAdded,
        onItemRemoved: handleItemRemoved,
        onCollaboratorJoined: handleCollaboratorJoined
    });

    isInitialized = true;
    currentProjectId = projectId;

    log('RealtimeUpdates', `Initialized real-time updates for project: ${projectId}`);
}

/**
 * Cleanup real-time updates when leaving a project
 */
export function cleanupRealtimeUpdates() {
    unsubscribeFromProject();
    isInitialized = false;
    currentProjectId = null;
    updateCallbacks.taskManager = null;
    updateCallbacks.projectsDashboard = null;
    log('RealtimeUpdates', 'Cleaned up real-time updates');
}

/**
 * Register a callback for task manager updates
 * @param {Function} callback - Callback function to call on updates
 */
export function registerTaskManagerCallback(callback) {
    updateCallbacks.taskManager = callback;
}

/**
 * Register a callback for projects dashboard updates
 * @param {Function} callback - Callback function to call on updates
 */
export function registerProjectsDashboardCallback(callback) {
    updateCallbacks.projectsDashboard = callback;
}

// =============================================================================
// EVENT HANDLERS
// =============================================================================

/**
 * Handle task-created event
 * @param {Object} data - Event data containing the new task
 */
function handleTaskCreated(data) {
    log('RealtimeUpdates', 'Task created event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
        return;
    }

    const { task, userName } = data;

    if (task && task.id) {
        // Add to state
        state.tasks.all.set(task.id, task);

        // Update byProject map
        const projectTasks = state.tasks.byProject.get(currentProjectId) || [];
        projectTasks.push(task);
        state.tasks.byProject.set(currentProjectId, projectTasks);

        // Show notification
        showRealtimeToast(`${userName || 'A collaborator'} created task: "${task.fields?.Name || 'New task'}"`);

        // Trigger UI update
        if (updateCallbacks.taskManager) {
            updateCallbacks.taskManager('created', task);
        }
    }
}

/**
 * Handle task-updated event
 * @param {Object} data - Event data containing the updated task
 */
function handleTaskUpdated(data) {
    log('RealtimeUpdates', 'Task updated event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
        return;
    }

    const { task, userName, changes } = data;

    if (task && task.id) {
        // Update in state
        state.tasks.all.set(task.id, task);

        // Update in byProject map
        const projectTasks = state.tasks.byProject.get(currentProjectId) || [];
        const taskIndex = projectTasks.findIndex(t => t.id === task.id);
        if (taskIndex >= 0) {
            projectTasks[taskIndex] = task;
            state.tasks.byProject.set(currentProjectId, projectTasks);
        }

        // Show notification with change details
        let changeDescription = 'updated';
        if (changes) {
            if (changes.Status) {
                changeDescription = `marked as ${changes.Status}`;
            } else if (changes.Name) {
                changeDescription = 'renamed';
            }
        }
        showRealtimeToast(`${userName || 'A collaborator'} ${changeDescription} task: "${task.fields?.Name || 'task'}"`);

        // Trigger UI update
        if (updateCallbacks.taskManager) {
            updateCallbacks.taskManager('updated', task);
        }
    }
}

/**
 * Handle task-deleted event
 * @param {Object} data - Event data containing the deleted task ID
 */
function handleTaskDeleted(data) {
    log('RealtimeUpdates', 'Task deleted event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
        return;
    }

    const { taskId, taskName, userName } = data;

    if (taskId) {
        // Remove from state
        state.tasks.all.delete(taskId);

        // Remove from byProject map
        const projectTasks = state.tasks.byProject.get(currentProjectId) || [];
        const filteredTasks = projectTasks.filter(t => t.id !== taskId);
        state.tasks.byProject.set(currentProjectId, filteredTasks);

        // Show notification
        showRealtimeToast(`${userName || 'A collaborator'} deleted task: "${taskName || 'task'}"`);

        // Trigger UI update
        if (updateCallbacks.taskManager) {
            updateCallbacks.taskManager('deleted', { id: taskId });
        }
    }
}

/**
 * Handle task-reordered event
 * @param {Object} data - Event data containing the new task orders
 */
function handleTaskReordered(data) {
    log('RealtimeUpdates', 'Task reordered event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
        return;
    }

    const { taskOrders, userName } = data;

    if (taskOrders && Array.isArray(taskOrders)) {
        // Update orders in state
        taskOrders.forEach(({ taskId, order }) => {
            const task = state.tasks.all.get(taskId);
            if (task) {
                task.fields.Order = order;
            }
        });

        // Show notification
        showRealtimeToast(`${userName || 'A collaborator'} reordered tasks`);

        // Trigger UI update
        if (updateCallbacks.taskManager) {
            updateCallbacks.taskManager('reordered', taskOrders);
        }
    }
}

/**
 * Handle project-status-changed event
 * @param {Object} data - Event data containing the new status
 */
function handleProjectStatusChanged(data) {
    log('RealtimeUpdates', 'Project status changed event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
        return;
    }

    const { status, userName } = data;

    showRealtimeToast(`${userName || 'A collaborator'} changed project status to: ${status}`);

    // Trigger UI update
    if (updateCallbacks.projectsDashboard) {
        updateCallbacks.projectsDashboard('statusChanged', { status });
    }
}

/**
 * Handle project-updated event
 * @param {Object} data - Event data containing the updated project info
 */
function handleProjectUpdated(data) {
    log('RealtimeUpdates', 'Project updated event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
        return;
    }

    const { project, userName, changes } = data;

    showRealtimeToast(`${userName || 'A collaborator'} updated the project`);

    // Trigger UI update
    if (updateCallbacks.projectsDashboard) {
        updateCallbacks.projectsDashboard('projectUpdated', { project, changes });
    }
}

/**
 * Handle item-added event
 * @param {Object} data - Event data containing the added item
 */
function handleItemAdded(data) {
    log('RealtimeUpdates', 'Item added event received', data);

    // Don't process if this is our own action
    if (data.userId === state.session.user?.id) {
